import sys

def count_overtakings(n, a, b):
    """
    Counts the number of overtakings by either runner during the race.

    Args:
    n (int): The duration of the race in minutes.
    a (list): The distances the first runner ran between minutes.
    b (list): The distances the second runner ran between minutes.

    Returns:
    int: The number of overtakings.
    """
    overtakings = 0
    first_runner_distance = 0
    second_runner_distance = 0
    leader = None

    for i in range(n):
        if i == 0:
            first_runner_distance = a[i]
            second_runner_distance = b[i]
            if first_runner_distance > second_runner_distance:
                leader = 1
            elif second_runner_distance > first_runner_distance:
                leader = 2
            else:
                leader = None
        else:
            first_runner_distance += a[i]
            second_runner_distance += b[i]
            if first_runner_distance > second_runner_distance:
                current_leader = 1
            elif second_runner_distance > first_runner_distance:
                current_leader = 2
            else:
                current_leader = None

            if leader is not None and current_leader is not None and leader != current_leader:
                overtakings += 1
            leader = current_leader

    return overtakings

def main():
    while True:
        try:
