using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<pair<int, int>> contests(N);
    for (auto& [L, R] : contests) {
        cin >> L >> R;
    }

    int Q;
    cin >> Q;

    vector<int> queries(Q);
    for (int& X : queries) {
        cin >> X;
    }

    const int max_rating = 5e5 + 10;
    vector<int> rating_increases(max_rating, 0);

    for (const auto& [L, R] : contests) {
        rating_increases[L]++;
        rating_increases[R + 1]--;
    }

    for (int i = 1; i < max_rating; ++i) {
        rating_increases[i] += rating_increases[i - 1];
    }

    for (int X : queries) {
        cout << X + rating_increases[X] << "\n";
    }

    return 0;
}

