#include <iostream>
#include <vector>

int main() {
    int Q;
    std::cin >> Q;

    std::vector<std::pair<long long, long long>> snakes;

    for (int i = 0; i < Q; i++) {
        int queryType;
        std::cin >> queryType;

        if (queryType == 1) {
            long long length;
            std::cin >> length;

            if (snakes.empty()) {
                snakes.push_back(std::make_pair(length, 0));
            } else {
                long long headPosition = snakes.back().first + snakes.back().second;
                snakes.push_back(std::make_pair(length, headPosition));
            }
        } else if (queryType == 2) {
            if (!snakes.empty()) {
                long long removedLength = snakes.front().first;
                snakes.erase(snakes.begin());

                for (auto& snake : snakes) {
                    snake.second -= removedLength;
                }
            }
        } else if (queryType == 3) {
            int k;
            std::cin >> k;

            if (k > 0 && k <= snakes.size()) {
                std::cout << snakes[k - 1].second << std::endl;
            }
        }
    }

    return 0;
}

#include <iostream>
#include <cmath>

long long count_squares(int R) {
    long long count = 0;
    int R_squared = (R - 1) * (R - 1);
    for (int i = -R; i <= R; i++) {
        int i_squared = i * i;
        for (int j = -R; j <= R; j++) {
            int j_squared = j * j;
            if (i_squared + j_squared <= R_squared) {
                count += 1;
            }
        }
    }
    return count;
}

int main() {
    int R;
    std::cin >> R;
    std::cout << count_squares(R) << std::endl;
    return 0;
}

#include <iostream>

long long factorial(int N) {
    long long result = 1;
    for (int i = 2; i <= N; i++) {
        result *= i;
        if (result > 3e18) break; // to prevent overflow
    }
    return result;
}

int main() {
