            std::cout << N << std::endl;
            break;
        }
        if (fact > X) {
            // handle error or assert, but according to problem, this won't happen
            break;
        }
        N++;
    }
    return 0;
}

#include <iostream>
#include <string>

int main() {
    int N;
    std::cin >> N;
    std::string S;
    std::cin >> S;

    if (N % 2 == 0) {
        std::cout << "No" << std::endl;
        return 0;
    }

    int mid_index = (N + 1) / 2 - 1;

    if (S[mid_index] != '/') {
        std::cout << "No" << std::endl;
        return 0;
    }

    bool is_first_half_ones = true;
    for (int i = 0; i < mid_index; i++) {
        if (S[i] != '1') {
            is_first_half_ones = false;
            break;
        }
    }

    if (!is_first_half_ones) {
        std::cout << "No" << std::endl;
        return 0;
    }

    bool is_second_half_twos = true;
    for (int i = mid_index + 1; i < N; i++) {
        if (S[i] != '2') {
            is_second_half_twos = false;
            break;
        }
    }

    if (is_first_half_ones && is_second_half_twos) {
        std::cout << "Yes" << std::endl;
    } else {
        std::cout << "No" << std::endl;
    }

    return 0;
}

from collections import deque

def main():
    H, W = map(int, input().split())
    grid = []
    for _ in range(H):
        grid.append(list(input()))

    start = None
    goal = None
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'G':
                goal = (i, j)

    if start is None or goal is None:
        print(-1)
        return

    queue = deque([(start[0], start[1], 0, None)])
    visited = set((start[0], start[1], None))
    while queue:
        x, y, moves, last_move = queue.popleft()
        if (x, y) == goal:
            print(moves)
            return
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] != '#':
                new_last_move = 'h' if dx == 0 else 'v'
                if last_move is None:
                    if (nx, ny, new_last_move) not in visited:
                        queue.append((nx, ny, moves + 1, new_last_move))
                        visited.add((nx, ny, new_last_move))
                elif last_move != new_last_move:
                    if (nx, ny, new_last_move) not in visited:
                        queue.append((nx, ny, moves + 1, new_last_move))
                        visited.add((nx, ny, new_last_move))
    print(-1)

