#include <iostream>
#include <unordered_map>

int main() {
    int A, B, C, D;
    std::cin >> A >> B >> C >> D;

    std::unordered_map<int, int> counts;
    counts[A]++;
    counts[B]++;
    counts[C]++;
    counts[D]++;

    bool canForm = false;

    for (auto& c : counts) {
        if (c.second >= 3) {
            for (auto& c2 : counts) {
                if (c2.first != c.first && c2.second >= 2) {
                    canForm = true;
                    break;
                } else if (c2.first != c.first && c2.second == 1) {
                    c2.second++;
                    if (c2.second == 2) {
                        canForm = true;
                        break;
                    }
                    c2.second--;
                }
            }
        } else if (c.second >= 2) {
            for (auto& c2 : counts) {
                if (c2.first != c.first && c2.second >= 3) {
                    canForm = true;
                    break;
                }
            }
        }
    }

    // Also consider adding a new card
    for (int newCard = 1; newCard <= 13; newCard++) {
        std::unordered_map<int, int> newCounts;
        newCounts[A]++;
        newCounts[B]++;
        newCounts[C]++;
        newCounts[D]++;
        newCounts[newCard]++;

        for (auto& c : newCounts) {
            if (c.second == 3) {
                for (auto& c2 : newCounts) {
                    if (c2.first != c.first && c2.second == 2) {
                        canForm = true;
                        break;
                    }
                }
            }
        }
        if (canForm) break;
    }

    if (canForm) {
        std::cout << "Yes" << std::endl;
    } else {
        std::cout << "No" << std::endl;
    }

    return 0;
}

