import sys
input = sys.stdin.readline

def main():
    N, M, H = map(int, input().split())
    soldiers = []
    for _ in range(N):
        L, R = map(int, input().split())
        soldiers.append((L, R))

    soldiers.sort(key=lambda x: (x[1], -x[0]))

    def can_defeat(pos, health):
        left, right = 0, N - 1
        while left <= right:
            mid = (left + right) // 2
            if soldiers[mid][1] < pos:
                left = mid + 1
            else:
                right = mid - 1
        idx = right
        if idx < 0:
            return False
        while idx >= 0 and soldiers[idx][0] > pos:
            idx -= 1
        if idx < 0:
            return False
        damage = 0
        for i in range(idx + 1):
            if soldiers[i][0] <= pos <= soldiers[i][1]:
                damage += 1
        return damage >= health

    for pos in range(M, -1, -1):
        if can_defeat(pos, H):
            H -= (pos - 1) * (idx + 1)
            if H <= 0:
                print(pos)
                return
        else:
            idx = -1
            damage = 0
            for i in range(N):
                if soldiers[i][0] <= pos <= soldiers[i][1]:
                    damage += 1
                    if damage >= H:
                        print(pos)
                        return
    print(-1)

