#include <string>
#include <vector>

int main() {
    std::string S;
    std::getline(std::cin, S);

    std::vector<int> A;
    A.reserve((S.length() - 1) / 2); // Reserve capacity
    int count = 0;
    for (int i = 1; i < S.length() - 1; ++i) {
        char c = S[i];
        if (c == '-') {
            ++count;
        } else if (c == '|') {
            A.push_back(count);
            count = 0;
        }
    }
    for (int num : A) {
        std::cout << num << " ";
    }
    std::cout << std::endl;
    return 0;
}
