    int N;
    cin >> N;
    vector<Point> vertices(N);
    for (int i = 0; i < N; ++i) {
        cin >> vertices[i].x >> vertices[i].y;
    }

    int windingNumber = 0;
    for (int i = 0; i < N; ++i) {
        Point p1 = vertices[i];
        Point p2 = vertices[(i + 1) % N];

        int crossProduct = (p2.x - p1.x) * (p1.y - 0) - (p2.y - p1.y) * (p1.x - 0);
        if (crossProduct > 0) {
            windingNumber++;
        } else if (crossProduct < 0) {
            windingNumber--;
        }
    }

    if (windingNumber != 0) {
        cout << "No" << endl;
    } else {
        cout << "Yes" << endl;
    }

    return 0;
}
