#include <vector>

using namespace std;

struct Point {
    int x, y;
};

int main() {
    int N;
    cin >> N;
    vector<Point> vertices(N);
    for (int i = 0; i < N; ++i) {
        cin >> vertices[i].x >> vertices[i].y;
    }

    bool isConvex = true;
    int orientation = 0;
    for (int i = 0; i < N; ++i) {
        Point p1 = vertices[i];
        Point p2 = vertices[(i + 1) % N];
        Point p3 = vertices[(i + 2) % N];

        int crossProduct = (p2.x - p1.x) * (p3.y - p2.y) - (p2.y - p1.y) * (p3.x - p2.x);
        if (orientation == 0) {
            orientation = crossProduct;
        } else if (orientation * crossProduct < 0) {
            isConvex = false;
            break;
        }
    }

    if (isConvex) {
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }

    return 0;
}
