        Point p1 = vertices[i];
        Point p2 = vertices[(i + 1) % N];
        Point p3 = vertices[(i + 2) % N];
        Point p4 = vertices[(i + 3) % N];

        int crossProduct = (p2.x - p1.x) * (p4.y - p3.y) - (p2.y - p1.y) * (p4.x - p3.x);
        if (crossProduct < 0) {
            countCross++;
        }
    }

    if (countCross == 0 || countCross == N) {
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }

    return 0;
}
