#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

struct TrieNode {
    TrieNode* children[2];
    int count;
    TrieNode() {
        children[0] = children[1] = nullptr;
        count = 0;
    }
};

void insert(TrieNode* root, int num) {
    TrieNode* node = root;
    for (int i = 59; i >= 0; i--) {
        int bit = (num >> i) & 1;
        if (!node->children[bit]) {
            node->children[bit] = new TrieNode();
        }
        node = node->children[bit];
        node->count++;
    }
}

int max_xor(TrieNode* root, int num, int k) {
    TrieNode* node = root;
    int result = 0;
    for (int i = 59; i >= 0; i--) {
        int bit = (num >> i) & 1;
        int opposite = bit ^ 1;
        if (node->children[opposite] && node->children[opposite]->count >= k) {
            result |= (1 << i);
            node = node->children[opposite];
        } else {
            node = node->children[bit];
        }
        k -= (node != nullptr);
    }
    return result;
}

int main() {
    int N, K;
    cin >> N >> K;
    vector<int> A(N);
    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }

    TrieNode* root = new TrieNode();
    for (int a : A) {
        insert(root, a);
    }

    int max_xor_value = 0;
    for (int a : A) {
        max_xor_value = max(max_xor_value, max_xor(root, a, K - 1));
    }

    cout << max_xor_value << endl;

    return 0;
}
