int main() {
    int N;
    long long S;
    std::cin >> N >> S;
    std::vector<long long> A(N);
    for (int i = 0; i < N; i++) {
        std::cin >> A[i];
    }

    long long total_sum = 0;
    for (int i = 0; i < N; i++) {
        total_sum += A[i];
    }

    if (S == total_sum) {
        std::cout << "Yes" << std::endl;
        return 0;
    }

    long long current_sum = 0;
    int left = 0;
    int right = 0;
    while (right < N) {
        current_sum += A[right];
        while (current_sum > S && left <= right) {
            current_sum -= A[left];
            left++;
        }
        if (current_sum == S) {
            std::cout << "Yes" << std::endl;
            return 0;
        }
        right++;
    }

    // Check for wraparound
    current_sum = 0;
    for (int i = 0; i < 2 * N; i++) {
        current_sum += A[i % N];
        if (current_sum == S) {
            std::cout << "Yes" << std::endl;
            return 0;
        }
        if (i >= N) {
            current_sum -= A[i - N];
        }
    }

    std::cout << "No" << std::endl;
    return 0;
