        cin >> P[i];
    }

    vector<pair<long long, int>> P_index;
    for (int i = 0; i < N; i++) {
        P_index.emplace_back(P[i], i);
    }
    sort(P_index.begin(), P_index.end());

    long long res = 0;
    for (auto& [p, i] : P_index) {
        if (M == 0) {
            break;
        }
        long long left = 0, right = static_cast<long long>(sqrt(M / p)) + 1;
        while (left <= right) {
            long long mid = (left + right) / 2;
            long long cost = mid * mid * p;
            if (cost <= M) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        long long units = right;
        if (units > 0) {
            res += units;
            M -= units * units * p;
        }
    }

    cout << res << endl;
    return 0;
}
