#include <iostream>
#include <queue>
#include <unordered_set>

using namespace std;

struct Cell {
    int x, y;
    Cell(int x = 0, int y = 0) : x(x), y(y) {}
};

int calculate_distance(int x, int y) {
    return max(abs(x), abs(y), abs(x - y));
}

int bfs(int x, int y) {
    queue<Cell> q;
    unordered_set<string> visited;
    q.push(Cell(0, 0));
    visited.insert("0 0");
    int steps = 0;
    while (!q.empty()) {
        int size = q.size();
        for (int i = 0; i < size; i++) {
            Cell cell = q.front();
            q.pop();
            if (cell.x == x && cell.y == y) {
                return steps;
            }
            int dx[] = {1, 0, -1, -1, 0, 1};
            int dy[] = {0, 1, 1, 0, -1, -1};
            for (int j = 0; j < 6; j++) {
                Cell next(cell.x + dx[j], cell.y + dy[j]);
                string key = to_string(next.x) + " " + to_string(next.y);
                if (visited.find(key) == visited.end()) {
                    q.push(next);
                    visited.insert(key);
                }
            }
        }
        steps++;
    }
    return -1;
}

int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        int x, y;
        cin >> x >> y;
        cout << calculate_distance(x, y) << endl;
    }
    return 0;
}
