        if (!visited[i]) {
            vector<int> cycle;
            int j = i;
            do {
                visited[j] = true;
                cycle.push_back(j);
                j = F[j];
            } while (j != i);
            cycles.push_back(cycle);
        }
    }

    long long result = 1;
    for (const auto& cycle : cycles) {
        int size = cycle.size();
        result = (result * pow(size, size, mod)) % mod;
    }
    cout << result << endl;
    return 0;
}

