using namespace std;

string compress(string s) {
    int n = s.size();
    vector<string> dp(n + 1);
    for (int i = 0; i <= n; i++) {
        dp[i] = "";
    }
    dp[0] = "";

    for (int i = 1; i <= n; i++) {
        dp[i] = s.substr(0, i);

        for (int j = 1; j <= i; j++) {
            if (i % j == 0 && s.substr(0, j) * (i / j) == s.substr(0, i)) {
                string compressed = to_string(i / j) + "(" + dp[j] + ")";
                if (compressed.size() < dp[i].size()) {
                    dp[i] = compressed;
                }
            }
        }

        for (int j = 1; j < i; j++) {
            string prev = dp[j];
            for (int k = 1; k <= 9; k++) {
                if (j * k + k <= i && s.substr(j, k) == s.substr(j, k, k)) {
                    string compressed = prev + to_string(k) + "(" + dp[j] + ")";
                    if (compressed.size() < dp[i].size()) {
                        dp[i] = compressed;
                    }
                }
            }
        }
    }

    return dp[n];
}

