#include <iostream>
#include <vector>

using namespace std;

class UnionFind {
public:
    vector<int> parent;
    vector<int> rank;
    int components;

    UnionFind(int n) : parent(n), rank(n, 0), components(n) {
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }
    }

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    bool union_(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX == rootY) {
            return false;
        }
        if (rank[rootX] < rank[rootY]) {
            parent[rootX] = rootY;
        } else if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
        } else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
        components--;
        return true;
    }
};

int minEdgesToRemove(int N, int M, vector<pair<int, int>>& edges) {
    UnionFind uf(N);
    int edgesToRemove = 0;
    for (auto& edge : edges) {
        int u = edge.first - 1;
        int v = edge.second - 1;
        if (!uf.union_(u, v)) {
            edgesToRemove++;
        }
    }
    return edgesToRemove;
}

int main() {
    int N, M;
    cin >> N >> M;

    vector<pair<int, int>> edges;
    for (int i = 0; i < M; i++) {
        int u, v;
        cin >> u >> v;
        edges.push_back(make_pair(u, v));
    }

    cout << minEdgesToRemove(N, M, edges) << endl;

    return 0;
}
