long long count_snake_numbers(long long L, long long R) {
    std::vector<std::vector<int>> dp(20, std::vector<int>(10, 0));
    for (int i = 1; i < 10; ++i) {
        dp[1][i] = 1;
    }
    for (int i = 2; i <= 18; ++i) {
        for (int j = 0; j < 10; ++j) {
            for (int k = 0; k <= j; ++k) {
                dp[i][j] += dp[i-1][k];
            }
        }
    }
    long long res = 0;
    std::string s = std::to_string(R);
    int len = s.size();
    for (int i = 0; i < len; ++i) {
        int digit = s[i] - '0';
        for (int j = 0; j < digit; ++j) {
            res += dp[len-i][j];
        }
        if (i == 0) {
            res += 1;
        }
    }
    if (R >= L) {
        --res;
    }
    s = std::to_string(L-1);
    len = s.size();
    for (int i = 0; i < len; ++i) {
        int digit = s[i] - '0';
        for (int j = 0; j < digit; ++j) {
            res -= dp[len-i][j];
        }
        if (i == 0) {
            res -= 1;
        }
    }
    return res;
}

