    std::string s = std::to_string(R);
    int len = s.size();
    for (int i = 0; i < len; ++i) {
        int digit = s[i] - '0';
        for (int j = 0; j < digit; ++j) {
            res += dp[len-i][j];
        }
        if (i == 0) {
            res += 1;
        }
