    for (int i = 1; i <= N; i++) {
        for (int j = 1; j <= X; j++) {
            if (products[i - 1].first.first > j) {
                dp[j][i] = dp[j][i - 1];
            } else {
                int utility = products[i - 1].first.second;
                int color = products[i - 1].second;
                int max_satisfaction = dp[j][i - 1];
                for (int k = 0; k < i; k++) {
