                    int total_price = products[k].first.first;
                    int total_utility = products[k].first.second;
                    int total_colors = 1;
                    for (int l = k + 1; l < i; l++) {
                        if (products[l].second == color) continue;
                        total_colors++;
                    }
                    max_satisfaction = max(max_satisfaction, dp[j - total_price][k] + total_utility + K * total_colors);
                }
                dp[j][i] = max(max_satisfaction, dp[j][i - 1]);
            }
        }
    }

    int max_satisfaction = 0;
    for (int i = 0; i <= X; i++) {
        max_satisfaction = max(max_satisfaction, dp[i][N]);
    }

