#include <numeric>
#include <algorithm>
#include <cmath>

const int MOD = 998244353;

int pow(int a, int b, int mod) {
    int res = 1;
    while (b > 0) {
        if (b & 1) res = (res * (long long)a) % mod;
        a = (a * (long long)a) % mod;
        b >>= 1;
    }
    return res;
}

int main() {
    int N;
    std::cin >> N;
    std::vector<int> A(N);
    for (int i = 0; i < N; ++i) {
        std::cin >> A[i];
    }

    int total_balls = std::accumulate(A.begin(), A.end(), 0);

    std::vector<int> C(total_balls + 1);
    C[0] = 1;
    for (int i = 0; i < N; ++i) {
        for (int j = total_balls; j >= 0; --j) {
            C[j + A[i]] = (C[j + A[i]] + C[j]) % MOD;
        }
    }

    int prob = 0;
    for (int i = 3; i <= total_balls; ++i) {
        prob = (prob + C[i] * pow(i, MOD - 2, MOD)) % MOD;
    }

    int total_ways = 1;
    for (int a : A) {
        total_ways = (total_ways * pow(a, a, MOD)) % MOD;
    }

    int inv_total_ways = pow(total_ways, MOD - 2, MOD);

    int ans = (prob * inv_total_ways) % MOD;
    std::cout << ans << std::endl;

    return 0;
}
