#include <vector>
#include <algorithm>
#include <cmath>

int gcd(int a, int b) {
    while (b) {
        a, b = b, a % b;
    }
    return a;
}

int main() {
    int N, K;
    std::cin >> N >> K;
    std::vector<int> A(N);
    for (int i = 0; i < N; ++i) {
        std::cin >> A[i];
    }

    std::vector<int> factors(1000001, 0);
    for (int i = 1; i <= 1000000; ++i) {
        for (int j = i; j <= 1000000; j += i) {
            factors[j] += 1;
        }
    }

    for (int i = 0; i < N; ++i) {
        int max_gcd = 0;
        for (int g = 1; g <= std::sqrt(A[i]); ++g) {
            if (A[i] % g == 0) {
                if (factors[g] >= K) {
                    max_gcd = std::max(max_gcd, g);
                }
                if (factors[A[i] / g] >= K && g != A[i] / g) {
                    max_gcd = std::max(max_gcd, A[i] / g);
                }
            }
        }
        std::cout << max_gcd << std::endl;
    }
    return 0;
}
