#include <iostream>
#include <vector>

class Node {
public:
    int value;
    Node* next;
    Node(int val) : value(val), next(nullptr) {}
};

class List {
private:
    Node* head;
    int size;
public:
    List() : head(nullptr), size(0) {}
    ~List() {
        while (head) {
            Node* temp = head;
            head = head->next;
            delete temp;
        }
    }
    void insert(int index, int value) {
        if (index == 0) {
            Node* newNode = new Node(value);
            newNode->next = head;
            head = newNode;
        } else {
            Node* current = head;
            for (int i = 0; i < index - 1; ++i) {
                current = current->next;
            }
            Node* newNode = new Node(value);
            newNode->next = current->next;
            current->next = newNode;
        }
        size++;
    }
    void print() {
        Node* current = head;
        while (current) {
            std::cout << current->value << " ";
            current = current->next;
        }
        std::cout << std::endl;
    }
};

int main() {
    int N;
    std::cin >> N;
    std::vector<int> P(N);
    for (int i = 0; i < N; ++i) {
        std::cin >> P[i];
    }
    List A;
    for (int i = 0; i < N; ++i) {
        A.insert(P[i] - 1, i + 1);
    }
    A.print();
    return 0;
}
