using namespace std;

void read_input(int& H, int& W, vector<string>& S) {
    cin >> H;
    cin >> W;
    for (int i = 0; i < H; ++i) {
        string s;
        cin >> s;
        S.push_back(s);
    }
}

bool find_rectangle(int H, int W, vector<string>& S) {
    int top_left_row = H;
    int top_left_col = W;
    int bottom_right_row = -1;
    int bottom_right_col = -1;

    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (S[i][j] == '#') {
                top_left_row = min(top_left_row, i);
                top_left_col = min(top_left_col, j);
                bottom_right_row = max(bottom_right_row, i);
                bottom_right_col = max(bottom_right_col, j);
            }
        }
    }

    if (top_left_row == H) {
        return false;
    }

    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (S[i][j] == '#') {
                if (!(top_left_row <= i && i <= bottom_right_row && top_left_col <= j && j <= bottom_right_col)) {
                    return false;
                }
            } else if (S[i][j] == '.') {
                if (top_left_row <= i && i <= bottom_right_row && top_left_col <= j && j <= bottom_right_col) {
                    return false;
                }
            }
        }
    }

    return true;
}

int main() {
    int H, W;
    vector<string> S;
    read_input(H, W, S);
    if (find_rectangle(H, W, S)) {
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }
    return 0;
}
