const int MAXN = 2 * 10 + 5;

class BIT {
public:
    int tree[MAXN];

    void update(int i, int x) {
        while i < MAXN {
            tree[i] = max(tree[i], x);
            i += i & -i;
        }
    }

    int query(int i) {
        int res = 0;
        while i > 0 {
            res = max(res, tree[i]);
            i -= i & -i;
        }
        return res;
    }
};

