int main() {
    int t;
    std::cin >> t;
    for (int _ = 0; _ < t; ++_) {
        int a1, a2, a3;
        std::cin >> a1 >> a2 >> a3;
        long long ans = 0;

        // (1, 2, 3) triangles
        int min_val = std::min({a1, a2, a3});
        ans += min_val;
        a1 -= min_val;
        a2 -= min_val;
        a3 -= min_val;

        // (2, 2, 2) triangles
        ans += a2 / 3;

        // (3, 3, 3) triangles
        ans += a3 / 3;

        std::cout << ans << std::endl;
    }
    return 0;
}
