int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> A(N);
    for (int i = 0; i < N; ++i) {
        cin >> A[i];
    }

    int Q;
    cin >> Q;

    for (int _ = 0; _ < Q; ++_) {
        int L, R;
        cin >> L >> R;
        --L;

        vector<int> mochi(A.begin() + L, A.begin() + R + 1);
        sort(mochi.begin(), mochi.end());

        int K = 0;
        int i = 0, j = mochi.size() - 1;
        while (i < j) {
            if (mochi[i] * 2 <= mochi[j]) {
                ++i;
                --j;
                ++K;
            } else {
                --j;
            }
        }
        cout << K << '\n';
    }

    return 0;
}

