#include <iostream>
#include <queue>
#include <unordered_set>

bool can_reach_end(long long N, int M, int A, int B, std::pair<int, int> intervals[], std::unordered_set<long long>& bad_squares) {
    // BFS queue
    std::queue<long long> queue;
    queue.push(1);
    std::unordered_set<long long> visited = {1};

    while (!queue.empty()) {
        long long current = queue.front();
        queue.pop();
        for (int i = A; i <= B; ++i) {
            long long next_square = current + i;
            if (next_square <= N && bad_squares.find(next_square) == bad_squares.end() && visited.find(next_square) == visited.end()) {
                if (next_square == N) {
                    return true;
                }
                queue.push(next_square);
                visited.insert(next_square);
            }
        }
    }
    return false;
}

int main() {
    long long N;
    int M, A, B;
    std::cin >> N >> M >> A >> B;
    std::pair<int, int> intervals[M];
    for (int i = 0; i < M; ++i) {
        std::cin >> intervals[i].first >> intervals[i].second;
    }

    std::unordered_set<long long> bad_squares;
    for (int i = 0; i < M; ++i) {
        for (long long j = intervals[i].first; j <= intervals[i].second; ++j) {
            bad_squares.insert(j);
        }
    }

    if (can_reach_end(N, M, A, B, intervals, bad_squares)) {
        std::cout << "Yes" << std::endl;
    } else {
        std::cout << "No" << std::endl;
    }
    return 0;
}
