// min_dyeing_steps.cpp

#include <iostream>
#include <vector>
#include <algorithm>

/**
 * Compute the minimum number of dyeing steps required to create a stripe pattern.
 *
 * @param sections A vector of integers representing the planned shade levels of each section.
 * @return The minimum number of dyeing steps required.
 */
int min_dyeing_steps(const std::vector<int>& sections) {
    if (sections.empty()) {
        return 0;
    }

    int n = sections.size();
    std::vector<int> dp(n);

    // Initialize the DP table
    dp[0] = 1;

    for (int i = 1; i < n; ++i) {
        dp[i] = dp[i - 1] + (sections[i] > sections[i - 1] ? 1 : 0);
    }

    // Find the maximum number of sections that can be dyed in one step
    int max_contiguous = 1;
    int current_contiguous = 1;
    for (int i = 1; i < n; ++i) {
        if (sections[i] >= sections[i - 1]) {
            current_contiguous++;
            max_contiguous = std::max(max_contiguous, current_contiguous);
        } else {
            current_contiguous = 1;
        }
    }

    // Adjust the DP table based on the maximum contiguous sections
    for (int i = 0; i < n; ++i) {
        dp[i] = std::min(dp[i], i + 1);
    }

    return *std::max_element(dp.begin(), dp.end());
}

int main() {
    try {
        int n;
        std::cin >> n;
        std::vector<int> sections(n);
        for (int i = 0; i < n; ++i) {
            std::cin >> sections[i];
        }
        std::cout << min_dyeing_steps(sections) << std::endl;
    } catch (const std::exception& e) {
        // Handle exceptions
    }
    return 0;
}

