void dfs(int u) {
    vis[u] = true;
    sz[u] = 1;
    dep[u] = 0;
    for (int v : graph[u]) {
        if (vis[v]) continue;
        parent[v] = u;
        dfs(v);
        sz[u] += sz[v];
        dep[u] = max(dep[u], dep[v] + 1);
    }
}

int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        u--;
        v--;
        graph[u].push_back(v);
        graph[v].push_back(u);
    }
    dfs(0);
    int centroid = -1;
    for (int i = 0; i < n; i++) {
        if (sz[i] * 2 >= n) {
            centroid = i;
            break;
        }
    }
    if (centroid == -1) {
        cout << 0 << endl;
        return 0;
    }
    int min_deletions = n;
    queue<int> q;
    q.push(centroid);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        int x = 0, y = 0;
        for (int v : graph[u]) {
            if (sz[v] > sz[u] - sz[v]) {
                x++;
            } else {
                y++;
            }
        }
        int deletions = n - (x + y * (x + 1));
        if (deletions < min_deletions) {
            min_deletions = deletions;
        }
    }
    cout << min_deletions << endl;
    return 0;
}
