using namespace std;

const int N = 3e5 + 10;
vector<int> graph[N];
int sz[N], dep[N];

void dfs(int u, int fa) {
    sz[u] = 1;
    for (int v : graph[u]) {
        if (v == fa) continue;
        dep[v] = dep[u] + 1;
        dfs(v, u);
        sz[u] += sz[v];
    }
}

int calc_deletions(int n) {
    dfs(1, 0);
    int min_deletions = n;
    for (int i = 1; i <= n; i++) {
        if (dep[i] == 1) {
            int x = sz[i] - 1;
            int leaves = 0;
            for (int v : graph[i]) {
                if (sz[v] > 1) continue;
                leaves++;
            }
            int y = leaves / (x > 0 ? x : 1);
            int deletions = n - (x + x * y);
            min_deletions = min(min_deletions, deletions);
        }
    }
    return min_deletions;
}

