using namespace std;

struct Node {
    int size;
    int leaves;
};

int calc_deletions(vector<vector<int>>& graph) {
    int N = graph.size();
    int min_deletions = N;

    for (int root = 0; root < N; root++) {
        unordered_map<int, Node> node_info;
        queue<pair<int, int>> q;
        q.push({root, -1});
        while (!q.empty()) {
            int node = q.front().first;
            int parent = q.front().second;
            q.pop();
            int size = 1;
            int leaves = 0;
            for (int child : graph[node]) {
                if (child != parent) {
                    q.push({child, node});
                    size += node_info[child].size;
                    leaves += node_info[child].leaves;
                }
            }
            if (leaves == 0) {
                leaves = 1;
            }
            node_info[node] = {size, leaves};
        }

        for (auto& info : node_info) {
            int size = info.second.size;
            int leaves = info.second.leaves;
            int deletions = N - size;
            if (deletions < min_deletions) {
                min_deletions = deletions;
            }
        }
    }

    return min_deletions;
}

