#include <iostream>
#include <vector>
#include <queue>
#include <unordered_map>
#include <algorithm>

using namespace std;

const int N = 3 * 100000;

struct Graph {
    vector<vector<int>> adj;
    Graph(int n) : adj(n) {}
    void add_edge(int u, int v) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
};

int calc_deletions(Graph& graph) {
    int n = graph.adj.size();
    int min_deletions = n;
    for (int root = 0; root < n; ++root) {
        vector<int> visited(n, 0);
        queue<pair<int, int>> q;
        q.push({root, -1});
        visited[root] = 1;
        while (!q.empty()) {
            int node = q.front().first;
            int parent = q.front().second;
            q.pop();
            int children = 0;
            int leaves = 0;
            for (int child : graph.adj[node]) {
                if (child != parent && !visited[child]) {
                    visited[child] = 1;
                    q.push({child, node});
                    children++;
                }
            }
            if (children == 0) {
                leaves = 1;
            }
            // calculate deletions
            int x = children;
            if (x > 0) {
                int total_leaves = leaves * x;
                for (int x_val = 1; x_val <= x; ++x_val) {
                    if (total_leaves % x_val == 0) {
                        int y = total_leaves / x_val;
                        int current_size = x_val + x_val * y;
                        if (current_size <= n) {
                            int deletions = n - current_size;
                            if (deletions < min_deletions) {
                                min_deletions = deletions;
                            }
                        }
                    }
                }
            }
        }
    }
    return min_deletions;
}

int main() {
    int n;
    cin >> n;
    Graph graph(n);
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        u--; v--;
        graph.add_edge(u, v);
    }
    cout << calc_deletions(graph) << endl;
    return 0;
}
