    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    queue = deque([(start, 0, None, None)])
    visited = set((start, None, None))

    while queue:
        (x, y), dist, last_dir_x, last_dir_y = queue.popleft()

