#include <iostream>
#include <vector>

const int mod = 998244353;

int64_t powmod(int64_t base, int64_t exponent) {
    int64_t result = 1;
    base = base % mod;
    while (exponent > 0) {
        if (exponent % 2 == 1) {
            result = (result * base) % mod;
        }
exponent = exponent >> 1;
        base = (base * base) % mod;
    }
    return result;
}

int64_t invmod(int64_t a) {
    return powmod(a, mod - 2);
}

int64_t binom(int64_t n, int64_t k) {
    if (k > n) {
        return 0;
    }
    if (k == 0 || k == n) {
        return 1;
    }
    int64_t num = 1;
    int64_t den = 1;
    for (int64_t i = 0; i < k; ++i) {
        num = (num * (n - i)) % mod;
        den = (den * (i + 1)) % mod;
    }
    return (num * invmod(den)) % mod;
}

int64_t solve(int64_t N, int64_t K) {
    if (N == 0 && K == 1) {
        return 1;
    } else if (N == 0) {
        return 0;
    }

    int64_t dp_prev = binom(N, 2);
    if (N > 0) {
        dp_prev = (dp_prev * invmod(2)) % mod;
    } else {
        dp_prev = 0;
    }
    int64_t ans = dp_prev;
    for (int64_t k = 2; k <= K; ++k) {
        int64_t dp_curr = ((dp_prev * (N - 1)) % mod + (dp_prev * (k - 1)) % mod) % mod;
        dp_curr = (dp_curr * invmod(k)) % mod;
        ans = (ans + dp_curr) % mod;
        dp_prev = dp_curr;
    }
    return ans;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int64_t T;
    std::cin >> T;
    for (int64_t _ = 0; _ < T; ++_) {
        int64_t N, K;
        std::cin >> N >> K;
        std::cout << solve(N, K) << '\n';
    }
    return 0;
}
