#include <iostream>
#include <vector>
#include <queue>
#include <unordered_set>

using namespace std;

struct Cell {
    int strength;
    int x, y;
    Cell(int strength, int x, int y) : strength(strength), x(x), y(y) {}
};

struct Compare {
    bool operator()(const Cell& a, const Cell& b) {
        return a.strength > b.strength;
    }
};

int main() {
    int H, W, X, P, Q;
    cin >> H >> W >> X >> P >> Q;
    P--; Q--;
    vector<vector<int>> S(H, vector<int>(W));
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            cin >> S[i][j];
        }
    }

    priority_queue<Cell, vector<Cell>, Compare> pq;
    unordered_set<pair<int, int>, hash_pair> visited;
    pq.push(Cell(S[P][Q], P, Q));
    visited.insert({P, Q});
    int max_strength = S[P][Q];

    vector<pair<int, int>> directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    while (!pq.empty()) {
        Cell current = pq.top();
        pq.pop();
        max_strength = max(max_strength, current.strength);
        for (auto& dir : directions) {
            int nx = current.x + dir.first;
            int ny = current.y + dir.second;
            if (nx >= 0 && nx < H && ny >= 0 && ny < W && visited.find({nx, ny}) == visited.end()) {
                if (S[nx][ny] * X < current.strength) {
                    pq.push(Cell(current.strength + S[nx][ny], nx, ny));
                    visited.insert({nx, ny});
                }
            }
        }
    }
    cout << max_strength << endl;
    return 0;
}
