using namespace std;

int main() {
    int H, W, X, P, Q;
    cin >> H >> W >> X >> P >> Q;
    P--; Q--;
    vector<vector<long long>> S(H, vector<long long>(W));
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            cin >> S[i][j];
        }
    }

    vector<vector<bool>> visited(H, vector<bool>(W, false));
    priority_queue<pair<long long, pair<int, int>>, vector<pair<long long, pair<int, int>>>, greater<pair<long long, pair<int, int>>>> pq;
    pq.push({-S[P][Q], {P, Q}});
    visited[P][Q] = true;
    long long max_strength = S[P][Q];

    vector<pair<int, int>> directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    while (!pq.empty()) {
        long long current_strength = -pq.top().first;
        int x = pq.top().second.first;
        int y = pq.top().second.second;
        pq.pop();
        for (auto& dir : directions) {
            int nx = x + dir.first;
            int ny = y + dir.second;
            if (0 <= nx && nx < H && 0 <= ny && ny < W && !visited[nx][ny]) {
                if (S[nx][ny] * X < current_strength) {
                    current_strength += S[nx][ny];
                    visited[nx][ny] = true;
                    pq.push({-current_strength, {nx, ny}});
                    max_strength = max(max_strength, current_strength);
                }
            }
        }
    }
    cout << max_strength << endl;
    return 0;
}
