#include <iostream>
#include <vector>
#include <string>
#include <cmath>
#include <numeric>
#include <ccomplex>

const int MOD = 998244353;
const int N = 3000;

// NTT-based convolution optimization
void ntt(std::vector<std::complex<double>>& a, bool inverse) {
    int n = a.size();
    if (n == 1) return;

    std::vector<std::complex<double>> even(n / 2), odd(n / 2);
    for (int i = 0; i < n; i += 2) {
        even[i / 2] = a[i];
        odd[i / 2] = a[i + 1];
    }

    ntt(even, inverse);
    ntt(odd, inverse);

    double ang = 2 * M_PI / n * (inverse ? -1 : 1);
    std::complex<double> w(1), wn(std::cos(ang), std::sin(ang));
    for (int i = 0; i < n / 2; ++i) {
        a[i] = even[i] + w * odd[i];
        a[i + n / 2] = even[i] - w * odd[i];
        w *= wn;
    }
}

void intt(std::vector<std::complex<double>>& a) {
    ntt(a, true);
    int n = a.size();
    for (int i = 0; i < n; ++i) {
        a[i].real() /= n;
    }
}

std::vector<int> convolve(const std::vector<int>& a, const std::vector<int>& b) {
    int n = 1;
    while (n < a.size() + b.size() - 1) n *= 2;
    std::vector<std::complex<double>> fa(n), fb(n);
    for (int i = 0; i < a.size(); ++i) fa[i] = a[i];
    for (int i = 0; i < b.size(); ++i) fb[i] = b[i];
    ntt(fa, false);
    ntt(fb, false);
    for (int i = 0; i < n; ++i) fa[i] *= fb[i];
    intt(fa);
    std::vector<int> res(n);
    for (int i = 0; i < n; ++i) res[i] = static_cast<int>(fa[i].real() + 0.5);
    return res;
}

// Expression evaluation
int eval_expression(const std::string& T) {
    // Simplified expression evaluation
    int value = 0;
    int sign = 1;
    int num = 0;
    for (char c : T) {
        if (c == '+') {
            value += sign * num;
            num = 0;
            sign = 1;
        } else if (c == '-') {
            value += sign * num;
            num = 0;
            sign = -1;
        } else if (std::isdigit(c)) {
            num = num * 10 + (c - '0');
        }
    }
    value += sign * num;
    return value;
}

int main() {
    std::string S = /* input */;
    int n = S.size();
    std::vector<int> coefficients(n);
    for (int i = 0; i < n; ++i) {
        if (S[i] == '?') {
            coefficients[i] = 1;
        }
    }
    std::vector<int> result = convolve(coefficients, coefficients);
    int total = 0;
    for (int i = 0; i < n; ++i) {
        total += result[i] * eval_expression(S.substr(i, 1));
        total %= MOD;
    }
    std::cout << total << std::endl;
    return 0;
}
