    int tampered = 0;

    // Compare the original and given records to find tampered numbers
    for (int i = 0; i < n; ++i) {
        if (original[i].morning != records[i].morning || original[i].afternoon != records[i].afternoon) {
            tampered += 2; // Both morning and afternoon counts are considered tampered
        }
    }

