#include <iostream>
#include <string>
#include <vector>

using namespace std;

const int INF = 1e9;

struct SegmentTree {
    vector<int> tree;
    int n;

    SegmentTree(int n) : n(n), tree(4 * n, INF) {}

    void update(int pos, int val) {
        updateHelper(1, 0, n - 1, pos, val);
    }

    int query(int l, int r) {
        return queryHelper(1, 0, n - 1, l, r);
    }

private:
    void updateHelper(int node, int start, int end, int pos, int val) {
        if (start == end) {
            tree[node] = min(tree[node], val);
            return;
        }
        int mid = (start + end) / 2;
        if (pos <= mid) {
            updateHelper(2 * node, start, mid, pos, val);
        } else {
            updateHelper(2 * node + 1, mid + 1, end, pos, val);
        }
        tree[node] = min(tree[2 * node], tree[2 * node + 1]);
    }

    int queryHelper(int node, int start, int end, int l, int r) {
        if (l > end || r < start) {
            return INF;
        }
        if (l <= start && end <= r) {
            return tree[node];
        }
        int mid = (start + end) / 2;
        return min(queryHelper(2 * node, start, mid, l, r),
                   queryHelper(2 * node + 1, mid + 1, end, l, r));
    }
};

int main() {
    int n;
    cin >> n;
    string s;
    cin >> s;

    long long ans = 0;
    SegmentTree segTree(n);
    vector<int> dp(n);

    for (int i = 0; i < n; i++) {
        if (s[i] == '<') {
            dp[i] = segTree.query(0, i - 1) + 1;
        } else {
            dp[i] = i;
            if (i > 0) {
                ans += i - segTree.query(0, i - 1) - 1;
            }
        }
        segTree.update(i, dp[i]);
    }

    cout << ans << endl;

    return 0;
}
