                ranks[pairs[j].second] = currentRank;
            }
            currentRank += count;
            count = 1;
            lastScore = pairs[i].first;
        }
    }

    // Handle the last group
    for (int j = N - count; j < N; j++) {
        ranks[pairs[j].second] = currentRank;
    }

    for (int rank : ranks) {
        std::cout << rank << std::endl;
