    vector<int> degrees(totalNodes + 1, 0);
    for (auto& neighbors : graph) {
        for (int neighbor : neighbors) {
            degrees[neighbor]++;
        }
    }

    stack<pair<int, int>> st;
    for (int i = 1; i <= totalNodes; ++i) {
