bool canDecompose(int N, int K, vector<vector<int>>& graph) {
    int totalNodes = N * K;
    if (totalNodes == 0) return false;

    vector<int> degrees(totalNodes + 1, 0);
    for (auto& neighbors : graph) {
        for (int neighbor : neighbors) {
            degrees[neighbor]++;
        }
    }

    stack<pair<int, int>> st;
    for (int i = 1; i <= totalNodes; ++i) {
        if (degrees[i] == 1) {
            st.push({i, 0});
        }
    }

    int pathsFound = 0;
    unordered_set<int> visited;

    while (!st.empty()) {
        int node = st.top().first;
        int depth = st.top().second;
        st.pop();

        if (visited.find(node) != visited.end()) continue;
        visited.insert(node);

        if (depth == K) {
            pathsFound++;
            continue;
        }

        for (int neighbor : graph[node]) {
            if (visited.find(neighbor) == visited.end()) {
                st.push({neighbor, depth + 1});
            }
        }
    }

    return pathsFound == N;
}

int main() {
    int N, K;
    cin >> N >> K;

    int totalNodes = N * K;
    vector<vector<int>> graph(totalNodes + 1);

    for (int i = 0; i < totalNodes - 1; ++i) {
        int u, v;
        cin >> u >> v;
        graph[u].push_back(v);
        graph[v].push_back(u);
    }

    if (canDecompose(N, K, graph)) {
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }

    return 0;
}
