    if (memo.find(state) != memo.end()) {
        return memo[state];
    }
    if (steps == 2 * N - 1) {
        if (x == N && y == N) {
            return s % M;
        } else {
            return -1;
        }
    }
    int max_score = -1;
    if (x < N) {
        max_score = max(max_score, dfs(x + 1, y, steps + 1, s * 10 + A[x][y]));
    }
    if (y < N && steps != 2 * N - 2) {
        max_score = max(max_score, dfs(x, y + 1, steps + 1, s * 10 + A[x][y]));
    }
    memo[state] = max_score;
    return max_score;
}

