#include <algorithm>

using namespace std;

const int mod = 998244353;

void ntt(vector<complex<double>>& a, bool inverse) {
    int n = a.size();
    for (int i = 1, j = 0; i < n; i++) {
        int bit = n >> 1;
        for (; j >= bit; bit >>= 1) j -= bit;
        j += bit;
        if (i < j) swap(a[i], a[j]);
    }
    complex<double> w(1), wn(cos(2 * M_PI / n), sin(2 * M_PI / n));
    if (inverse) wn = conj(wn);
    for (int i = 1; i < n; i++) {
        w *= wn;
        for (int j = 0, k = i; k < n; k += i, j++) {
            complex<double> u = a[j], v = w * a[j + i];
            a[j] = u + v;
            a[j + i] = u - v;
        }
    }
    if (inverse) {
        double inv = 1.0 / n;
        for (int i = 0; i < n; i++) a[i] *= inv;
    }
}

vector<complex<double>> conv(vector<complex<double>> a, vector<complex<double>> b) {
    int n = 1;
    while (n < a.size() + b.size() - 1) n <<= 1;
    a.resize(n);
    b.resize(n);
    ntt(a, false);
    ntt(b, false);
    for (int i = 0; i < n; i++) a[i] *= b[i];
    ntt(a, true);
    return a;
}

