long long min_steps(long long x1, long long y1, long long z1, long long x2, long long y2, long long z2, long long K) {
    long long dx = abs(x2 - x1);
    long long dy = abs(y2 - y1);
    long long dz = abs(z2 - z1);

    long long total_steps = dx + dy + dz;
    long long ans = total_steps;
