                int diff = A[index2] - A[index1];
                int target = A[index1] - diff;
                if (num_indices.find(target) != num_indices.end()) {
                    vector<int>& target_indices = num_indices[target];
                    int left = 0, right = target_indices.size() - 1;
                    while (left <= right) {
                        int mid = (left + right) / 2;
                        if (target_indices[mid] < index1) {
                            left = mid + 1;
                        } else {
                            right = mid - 1;
                        }
                    }
                    if (left < target_indices.size() && target_indices[left] > index1 && target_indices[left] < index2) {
                        count += (target_indices.size() - left);
                    }
                }
