#include <iostream>
#include <queue>
#include <unordered_set>
#include <vector>

using namespace std;

struct State {
    int x, y, moves;
    char last_move; // 'h' for horizontal, 'v' for vertical, '\0' for none
};

bool is_valid(int x, int y, int H, int W, vector<vector<char>>& grid) {
    return 0 <= x && x < H && 0 <= y && y < W && grid[x][y] != '#';
}

int main() {
    int H, W;
    cin >> H >> W;

    vector<vector<char>> grid(H, vector<char>(W));
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            cin >> grid[i][j];
        }
    }

    pair<int, int> start, goal;
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (grid[i][j] == 'S') {
                start = {i, j};
            } else if (grid[i][j] == 'G') {
                goal = {i, j};
            }
        }
    }

    if (start.first == -1 || goal.first == -1) {
        cout << -1 << endl;
        return 0;
    }

    queue<State> q;
    q.push({start.first, start.second, 0, '\0'});
    unordered_set<pair<pair<int, int>, char>, hash_pair> visited;
    visited.insert({{start.first, start.second}, '\0'});

    while (!q.empty()) {
        State current = q.front();
        q.pop();

        if (current.x == goal.first && current.y == goal.second) {
            cout << current.moves << endl;
            return 0;
        }

        vector<pair<int, int>> moves = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (auto& move : moves) {
            int nx = current.x + move.first;
            int ny = current.y + move.second;

            if (!is_valid(nx, ny, H, W, grid)) {
                continue;
            }

            char new_last_move = (move.first != 0) ? 'v' : 'h';
            if (current.last_move == '\0' || current.last_move != new_last_move) {
                if (visited.find({{nx, ny}, new_last_move}) == visited.end()) {
                    q.push({nx, ny, current.moves + 1, new_last_move});
                    visited.insert({{nx, ny}, new_last_move});
                }
            }
        }
    }

    cout << -1 << endl;
    return 0;
}

struct hash_pair {
    size_t operator()(const pair<pair<int, int>, char>& p) const {
        hash<int> int_hash;
        hash<char> char_hash;
        return int_hash(p.first.first) ^ int_hash(p.first.second) ^ char_hash(p.second);
    }
};
