#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

struct Point {
    int x, y;
    Point(int x = 0, int y = 0) : x(x), y(y) {}
};

bool orientation(const Point& p, const Point& q, const Point& r) {
    int val = (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y);
    if (val == 0) return true; // Collinear
    return val > 0; // Clockwise or Counterclockwise
}

int max_triangles(std::vector<Point>& points) {
    int n = points.size();
    std::sort(points.begin(), points.end(), [](const Point& a, const Point& b) {
        return a.x < b.x;
    });

    int count = 0;
    for (int i = 0; i < n; ++i) {
        std::vector<Point> left, right;
        for (int j = i + 1; j < n; ++j) {
            if (orientation(points[i], points[j], points[j-1])) {
                right.push_back(points[j]);
            } else {
                left.push_back(points[j]);
            }
        }
        count += std::min(left.size(), right.size());
    }
    return count;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<Point> points(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> points[i].x >> points[i].y;
    }
    std::cout << max_triangles(points) << std::endl;
    return 0;
}
