#include <bits/stdc++.h>
using namespace std;

class FenwickTree {
public:
    FenwickTree(int n) : n(n), tree(n + 1, 0) {}

    void update(int i, int val) {
        while (i <= n) {
            tree[i] += val;
            i += i & -i;
        }
    }

    int query(int i) {
        int sum = 0;
        while (i > 0) {
            sum += tree[i];
            i -= i & -i;
        }
        return sum;
    }

    int range_query(int i, int j) {
        return query(j) - query(i - 1);
    }

private:
    int n;
    vector<int> tree;
};

int solve(long long N) {
    int ans = 0;
    for (int y = 1; y * y <= N; y++) {
