    std::sort(cakes.begin(), cakes.end(), compareCakes);

    int total_price = 0;
    std::vector<bool> used(N, false);
    for (int i = 0; i < K; ++i) {
        int max_price = 0;
        int pair_first = -1, pair_second = -1;
        for (int j = 0; j < N; ++j) {
            if (used[j]) continue;
            for (int k = j + 1; k < N; ++k) {
                if (used[k]) continue;
                int price = std::max({cakes[j].X + cakes[k].X, cakes[j].Y + cakes[k].Y, cakes[j].Z + cakes[k].Z});
                if (price > max_price) {
                    max_price = price;
                    pair_first = j;
                    pair_second = k;
                }
            }
        }
        used[pair_first] = true;
        used[pair_second] = true;
        total_price += max_price;
    }

    return total_price;
}

