import sys

def find(parent, i):
    if parent[i] != i:
        parent[i] = find(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)

    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def distance(w1, w2):
    return max(abs(w1[0] - w2[0]), abs(w1[1] - w2[1]))

def connecting_wells(wells):
    n = len(wells)
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            dist = distance(wells[i], wells[j])
            edges.append((dist, i, j))

    edges.sort()
    parent = list(range(n))
    rank = [0] * n
    connected_components = n
    min_time = 0

