using namespace std;

int min_length(vector<int>& arr) {
    unordered_map<int, int> freq;
    for (int num : arr) {
        freq[num++];
    }
    int count_odd = 0;
    for (auto& pair : freq) {
        if (pair.second > 1) {
            if (pair.second % 2 == 1) count_odd++;
        }
    }
    return count_odd + (arr.size() - (arr.size() - count_odd) % 2);
}

