#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> A(N), B(N);
    for (int& a : A) cin >> a;
    for (int& b : B) cin >> b;

    long long sum_A = 0, sum_B = 0;
    int count_A_neg = 0, count_B_neg = 0;
    for (int a : A) {
        if (a != -1) sum_A += a;
        else count_A_neg++;
    }
    for (int b : B) {
        if (b != -1) sum_B += b;
        else count_B_neg++;
    }

    long long total_sum = sum_A + sum_B;
    if (total_sum < 0) {
        cout << "No" << '\n';
        return 0;
    }

    if (total_sum % N != 0) {
        cout << "No" << '\n';
        return 0;
    }
    long long target = total_sum / N;

    if (count_A_neg + count_B_neg > N || (sum_A + sum_B + count_A_neg + count_B_neg < target * N)) {
        cout << "No" << '\n';
        return 0;
    }

    cout << "Yes" << '\n';
    return 0;
}
