#include <algorithm>

using namespace std;

int main() {
    int N;
    cin >> N;

    vector<int> A(N), B(N);
    for (int i = 0; i < N; ++i) cin >> A[i];
    for (int i = 0; i < N; ++i) cin >> B[i];

    int sum_A = 0, sum_B = 0;
    int count_A_neg = 0, count_B_neg = 0;
    for (int a : A) {
        if (a != -1) sum_A += a;
        else count_A_neg++;
    }
    for (int b : B) {
        if (b != -1) sum_B += b;
        else count_B_neg++;
    }

    int total_sum = sum_A + sum_B;

    if (total_sum < 0) {
        cout << "No" << endl;
        return 0;
    }

    if (total_sum % N != 0) {
        cout << "No" << endl;
        return 0;
    }
    int target = total_sum / N;

    int remaining_A = target * N - sum_A - count_A_neg;
    int remaining_B = target * N - sum_B - count_B_neg;

    if (remaining_A < 0 || remaining_B < 0) {
        cout << "No" << endl;
        return 0;
    }

    cout << "Yes" << endl;
    return 0;
