using namespace std;
const int mod = 998244353;

long long powmod(long long a, long long b, long long mod) {
    long long res = 1;
    while (b > 0) {
        if (b & 1) res = (res * a) % mod;
        a = (a * a) % mod;
        b >>= 1;
    }
    return res;
}

long long calc(int a1, int a2, int a3) {
    if (a3 - 1 < std::max(a1, a2) || a3 > a1 + a2) return 0;
    long long res = 9 * powmod(10, a1 - 1, mod) * powmod(10, a2 - 1, mod);
    res %= mod;
    return res;
}

