        long long ans = calc(a1, a2, a3) + calc(a2, a1, a3);
        ans %= mod;
        if (a1 == a2 && a2 == a3) ans -= 9 * powmod(10, a1 - 1, mod);
        ans %= mod;
        std::cout << ans << '\n';
    }
    return 0;
