#include <iostream>
#include <string>
#include <bitset>

const int MAX_T_LEN = 10;
const int NUM_QUESTIONS = 4;

bool can_contain(const std::string& t, const std::string& u) {
    int t_len = t.size();
    int u_len = u.size();
    if (u_len > t_len) return false;

    // Find positions of '?' in t
    std::bitset<MAX_T_LEN> question_pos;
    int question_cnt = 0;
    for (int i = 0; i < t_len; ++i) {
        if (t[i] == '?') {
            question_pos[i] = 1;
            question_cnt++;
        }
    }
    if (question_cnt != NUM_QUESTIONS) return false;

    // Check if u can be a substring of t
    for (int start = 0; start <= t_len - u_len; ++start) {
        bool match = true;
        for (int i = 0; i < u_len; ++i) {
            if (t[start + i] != '?' && t[start + i] != u[i]) {
                match = false;
                break;
            }
        }
        if (match) {
            // Check if u can be formed by replacing '?' in t
            std::bitset<MAX_T_LEN> used_question;
            for (int i = 0; i < u_len; ++i) {
                if (t[start + i] == '?') {
                    used_question[start + i] = 1;
                }
            }
            if (used_question.count() > NUM_QUESTIONS) continue;

            // Try all possible replacements for '?' in t
            for (int mask = 0; mask < (1 << NUM_QUESTIONS); ++mask) {
                std::string temp_t = t;
                int question_idx = 0;
                for (int i = 0; i < t_len; ++i) {
                    if (t[i] == '?') {
                        temp_t[i] = 'a' + ((mask >> question_idx) & 1);
                        question_idx++;
                    }
                }
                if (temp_t.substr(start, u_len) == u) return true;
            }
        }
    }
    return false;
}

int main() {
    std::string t, u;
    std::cin >> t >> u;
    if (can_contain(t, u)) {
        std::cout << "Yes" << std::endl;
    } else {
        std::cout << "No" << std::endl;
    }
    return 0;
}
