    inv_fact.resize(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) {
        fact[i] = (fact[i - 1] * i) % MOD;
    }
    inv_fact[n] = pow(fact[n], MOD - 2, MOD);
    for (int i = n - 1; i >= 0; --i) {
