 *
 * @param sticks A vector of stick lengths.
 * @return The maximum number of breaks.
 */
int maxBreaks(const std::vector<int>& sticks) {
    int total_breaks = 0;
    for (int length : sticks) {
        if (length > 1) {
            total_breaks += length - 1;
        }
    }
    return total_breaks;
}

