#include <iostream>
#include <queue>
#include <unordered_set>
#include <vector>

using namespace std;

const int MAX_N = 2e5 + 5;

struct State {
    vector<int> A;
    vector<int> B;
    State(vector<int> A, vector<int> B) : A(A), B(B) {}
};

struct HashFunction {
    size_t operator()(const State& state) const {
        size_t hash = 0;
        for (int i = 0; i < state.A.size(); ++i) {
            hash = hash * 31 + state.A[i];
        }
        for (int i = 0; i < state.B.size(); ++i) {
            hash = hash * 31 + state.B[i];
        }
        return hash;
    }
};

bool is_goal_state(const State& state, int X, int N) {
    for (int i = 0; i < N; ++i) {
        if (i != X - 1 && (state.A[i] != 0 || state.B[i] != 0)) {
            return false;
        }
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, X;
    cin >> N >> X;
    vector<int> A(N), B(N);
    for (int i = 0; i < N; ++i) {
        cin >> A[i];
    }
    for (int i = 0; i < N; ++i) {
        cin >> B[i];
    }
    vector<int> P(N), Q(N);
    for (int i = 0; i < N; ++i) {
        cin >> P[i];
        --P[i];
    }
    for (int i = 0; i < N; ++i) {
        cin >> Q[i];
        --Q[i];
    }

    State initial_state(A, B);
    queue<State> q;
    q.push(initial_state);
    unordered_set<State, HashFunction> visited;
    visited.insert(initial_state);
    int operations = 0;

    while (!q.empty()) {
        int size = q.size();
        for (int i = 0; i < size; ++i) {
            State current_state = q.front();
            q.pop();

            if (is_goal_state(current_state, X, N)) {
                cout << operations << '\n';
                return 0;
            }

            for (int j = 0; j < N; ++j) {
                if (current_state.A[j] == 0 && current_state.B[j] == 0) {
                    continue;
                }

                State new_state(current_state.A, current_state.B);
                int red_balls = new_state.A[j];
                int blue_balls = new_state.B[j];
                new_state.A[j] = 0;
                new_state.B[j] = 0;
                new_state.A[P[j]] += red_balls;
                new_state.B[Q[j]] += blue_balls;

                if (visited.find(new_state) == visited.end()) {
                    q.push(new_state);
                    visited.insert(new_state);
                }
            }
        }
        ++operations;
    }

    cout << -1 << '\n';
    return 0;
}
