def can_pay(coins, cost):
    memo = {}
    def dp(coins, cost):
        if (tuple(coins), cost) in memo:
            return memo[(tuple(coins), cost)]
        if cost == 0:
            return True
        if cost < 0:
            return False
        result = False
        denominations = [1, 5, 10, 50, 100, 500]
        for i in range(len(denominations)):
            if coins[i] > 0 and cost >= denominations[i]:
                new_coins = list(coins)
                new_coins[i] -= 1
                result = result or dp(tuple(new_coins), cost - denominations[i])
        memo[(tuple(coins), cost)] = result
        return result
    return dp(coins, cost)

