    int count_k = 0;
    int first_k = -1, last_k = -1;
    for (int i = 0; i < n; i++) {
        if (nums[i] == k) {
            count_k++;
            if (first_k == -1) first_k = i;
            last_k = i;
        }
    }

    if (count_k > n / 2) return 0;

    int max_count = 0;
    for (int i = first_k; i <= last_k; i++) {
        int curr_count = 0;
        int other_count = 0;
        for (int j = i; j < n; j++) {
            if (nums[j] == k) curr_count++;
            else other_count++;
            if (curr_count > other_count && curr_count > max_count) {
                max_count = curr_count;
            }
        }
    }
    for (int i = last_k; i >= first_k; i--) {
        int curr_count = 0;
        int other_count = 0;
        for (int j = i; j >= 0; j--) {
            if (nums[j] == k) curr_count++;
            else other_count++;
            if (curr_count > other_count && curr_count > max_count) {
                max_count = curr_count;
            }
        }
    }
    if (max_count > 0) return 1;
    return 2;
}

int main() {
    int t;
    cin >> t;
    while (t--) {
        int n, k;
        cin >> n >> k;
        vector<int> nums(n);
        for (int i = 0; i < n; i++) {
            cin >> nums[i];
        }
        cout << min_operations(nums, k) << endl;
    }
    return 0;
}
