using namespace std;

int min_operations(vector<int>& nums, int k) {
    int n = nums.size();
    int first_k = -1, last_k = -1;
    for (int i = 0; i < n; i++) {
        if (nums[i] == k) {
            if (first_k == -1) first_k = i;
            last_k = i;
        }
    }

    unordered_map<int, int> count;
    for (int i = 0; i < n; i++) {
        count[nums[i]]++;
    }
    if (count[k] > count.begin()->second) {
        return 0;
    }

    int left = 0, right = n - 1;
    int left_count = 0, right_count = 0;
    for (int i = first_k; i <= last_k; i++) {
        if (nums[i] == k) {
            left_count++;
        }
    }
    for (int i = last_k; i >= first_k; i--) {
        if (nums[i] == k) {
            right_count++;
        }
    }
    if (left_count == count[k] || right_count == count[k]) {
        return 1;
    }
    return 2;
}

int main() {
    int t;
    cin >> t;
    while (t--) {
        int n, k;
        cin >> n >> k;
        vector<int> nums(n);
        for (int i = 0; i < n; i++) {
