int maxOnes(int n, int k, std::string s) {
    int ones = 0;
    for (char c : s) {
        if (c == '1') {
            ones++;
        }
    }

    int operations = 0;
    for (int i = n - 1; i > 0; i--) {
        if (s[i] == '1' && s[i - 1] == '0' && operations < k) {
            s[i - 1] = '1';
            ones++;
            operations++;
        }
    }

    return ones;
}

