int maxOnes(int n, int k, std::string s) {
    int ones = 0;
    for (char c : s) {
        if (c == '1') ones++;
    }

    int left = 0, right = n - 1;
    while (k > 0 && left < right) {
        if (s[right] == '1') {
            if (s[left] == '0') {
                s[left] = '1';
                ones++;
                k--;
            }
            right--;
        } else {
            left++;
        }
    }

    return ones;
}

