#include <iostream>
#include <unordered_map>

using namespace std;

void solve() {
    int n, c;
    cin >> n >> c;
    string s;
    cin >> s;

    // Count the frequency of each language
    int freq[5] = {0}; // Assuming languages are A, B, C, D, E
    for (char& char_ : s) {
        switch(char_) {
            case 'A': freq[0]++; break;
            case 'B': freq[1]++; break;
            case 'C': freq[2]++; break;
            case 'D': freq[3]++; break;
            case 'E': freq[4]++; break;
        }
    }

    // Calculate the cost of using a translator for each person
    int translator_cost = (n * (n + 1)) / 2;

    // Calculate the cost of learning a language
    int learn_cost = c;
    for (int i = 0; i < 5; i++) {
        if (freq[i] > 0) {
            int cost = c + (n - freq[i]) * (n - freq[i] + 1) / 2;
            learn_cost = min(learn_cost, cost);
        }
    }

    cout << min(learn_cost, translator_cost) << endl;
}

int main() {
    int t;
    cin >> t;
    for (int _ = 0; _ < t; _++) {
