class Solution {
public:
    int distributeCandies(int n, int limit) {
        int memo[51][51][51] = {{{0}}};
        return dp(n, limit, 3, 0, 0, memo);
    }
    int dp(int n, int limit, int children, int currChild, int currCandies, int memo[51][51][51]) {
        if (n < 0) return 0;
        if (currChild == children) return n == 0 ? 1 : 0;
        if (memo[currCandies][n][currChild] != 0) return memo[currCandies][n][currChild];
