int min_operations(const std::string& s) {
    int n = s.size();
    int diff0 = 0;
    int diff1 = 0;

    for (int i = 0; i < n; ++i) {
        if (i % 2 == 0) {
            if (s[i] != '0') ++diff0;
            if (s[i] != '1') ++diff1;
        } else {
            if (s[i] != '1') ++diff0;
            if (s[i] != '0') ++diff1;
        }
    }

    return (diff0 == 0 || diff1 == 0) ? 1 : 2;
}

