    long long distributeCandies(int n, int limit) {
        const int mod = 1e9 + 7;
        long long dp[3][limit + 1];
        memset(dp, 0, sizeof(dp));
        dp[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= 3; j++) {
                for (int k = 0; k <= limit && k <= i; k++) {
                    dp[j - 1][k] = (dp[j - 1][k] + (j > 1 ? dp[j - 2][i - k] : 0)) % mod;
                }
            }
        }
        long long res = 0;
        for (int i = 0; i <= limit; i++) {
            res = (res + dp[2][i]) % mod;
        }
        return res;
    }
};

