class Solution {
public:
    int findMaximumLength(vector<int>& nums) {
        int n = nums.size();
        int max_len = 1;
        int sum = 0;
        unordered_map<int, int> compress;
        vector<int> coord;
        coord.push_back(0);
        for (int num : nums) {
            sum += num;
            coord.push_back(sum);
        }
        sort(coord.begin(), coord.end());
        for (int i = 0; i < coord.size(); i++) {
            compress[coord[i]] = i;
        }
        BIT bit(coord.size());
        for (int x : coord) {
            int idx = compress[x];
            max_len = max(max_len, bit.query(idx) + 1);
            bit.update(idx, 1);
        }
        return max_len;
    }
};

class BIT {
private:
    vector<int> bit;
    int n;
public:
    BIT(int n) : n(n), bit(n + 1, 0) {}
    int query(int i) {
        int res = 0;
        while (i > 0) {
            res += bit[i];
            i -= i & -i;
        }
        return res;
    }
    void update(int i, int val) {
        while (i <= n) {
            bit[i] += val;
            i += i & -i;
        }
    }
}

