#include <iostream>
#include <vector>

void solve(int N, int K) {
    if (K == 1 && N > 1) {
        std::cout << -1 << std::endl;
        return;
    } else if (N == 1 && K == 1) {
        std::cout << 1 << std::endl;
        return;
    }

    std::vector<int> permutation(N);
    for (int i = 0; i < N; ++i) {
        permutation[i] = (i + K) % N + 1;
    }

    bool valid = true;
    for (int i = 0; i < N; ++i) {
        if (permutation[i] % K == (i + 1) % K) {
            valid = false;
            break;
        }
    }

    if (valid) {
        for (int num : permutation) {
            std::cout << num << " ";
        }
        std::cout << std::endl;
    } else {
        std::cout << -1 << std::endl;
    }
}

int main() {
    int T;
    std::cin >> T;
    for (int _ = 0; _ < T; ++_) {
        int N, K;
        std::cin >> N >> K;
        solve(N, K);
    }
    return 0;
}
