    int ones_s2 = std::count(s2.begin(), s2.end(), '1');
    int ones_s3 = std::count(s3.begin(), s3.end(), '1');
    int total_ones = ones_s1 + ones_s2 + ones_s3;

    if (total_ones == 0 || total_ones == 3 * n) {
        return 0;
    } else if (total_ones % n == 0) {
        int target_ones = total_ones / n;
        int ops_to_ones = 0;
        int ops_to_zeros = 0;
        for (int i = 0; i < n; i++) {
            if (s1[i] == '0') ops_to_ones++;
            if (s2[i] == '0') ops_to_ones++;
            if (s3[i] == '0') ops_to_ones++;
            if (s1[i] == '1') ops_to_zeros++;
            if (s2[i] == '1') ops_to_zeros++;
            if (s3[i] == '1') ops_to_zeros++;
        }
        ops_to_ones = std::max(0, ops_to_ones - 2 * target_ones);
        ops_to_zeros = std::max(0, ops_to_zeros - 2 * (n - target_ones));
        return std::min(ops_to_ones, ops_to_zeros);
    } else {
        return -1;
    }
}

int main() {
    int t;
    std::cin >> t;
    for (int _ = 0; _ < t; _++) {
        int n;
        std::cin >> n;
        std::string s1, s2, s3;
        std::cin >> s1 >> s2 >> s3;
        std::cout << min_operations(n, s1, s2, s3) << std::endl;
    }
    return 0;
}
