int64_t gcd(int64_t a, int64_t b) {
    if (b == 0) return a;
    return gcd(b, a % b);
}

int64_t lcm(int64_t a, int64_t b) {
    return a * b / gcd(a, b);
}

int64_t f(int N, int M) {
    if (N == 2) {
        int64_t ans = (int64_t)M * (M - 1) * (M - 2) / 2 + M;
        ans %= MOD;
        return ans;
    } else {
        return 0;
    }
}

