    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int T;
    cin >> T;
    for (int i = 0; i < T; i++) {
        int N, M;
        cin >> N >> M;
        int64_t ans = f(N, M);
        cout << (int)ans << "\n";
    }

    return 0;
}

