#include <bits/stdc++.h>
using namespace std;

bool is_smoothly_increasing(vector<int> arr) {
    if (arr.size() == 1) return true;
    for (int i = 0; i < arr.size() - 1; i++) {
        if (arr[i] >= arr[i+1]) return false;
    }
    vector<int> diff_arr;
    for (int i = 1; i < arr.size(); i++) {
        diff_arr.push_back(arr[i] - arr[i-1]);
    }
    return is_smoothly_increasing(diff_arr);
}

void solve() {
    int n;
    cin >> n;
    vector<int> arr(n);
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }
    string result = "";
    for (int i = 0; i < n; i++) {
        vector<int> new_arr;
        for (int j = 0; j < i; j++) {
            new_arr.push_back(arr[j]);
        }
        for (int j = i + 1; j < n; j++) {
            new_arr.push_back(arr[j]);
        }
        if (is_smoothly_increasing(new_arr)) {
            result += "1";
        } else {
            result += "0";
        }
    }
    cout << result << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    cin >> t;
    while (t--) {
        solve();
    }
    return 0;
}
