#include <iostream>
#include <string>
#include <vector>

using namespace std;

long long min_cost_to_transform(string A, string B) {
    int n = A.size();
    int m = B.size();
    vector<vector<long long>> dp(n + 1, vector<long long>(m + 1, -1));

    function<long long(int, int)> dfs = [&](int i, int j) {
        if (j == m) return 0;
        if (i == n) return -1;
        if (dp[i][j] != -1) return dp[i][j];

        long long cost = -1;
        if (A[i] == B[j]) {
            cost = dfs(i + 1, j + 1);
        } else {
            long long remove_cost = dfs(i + 1, j) + i + 1;
            cost = remove_cost;
        }
        return dp[i][j] = cost;
    };

    long long res = dfs(0, 0);
    return res == -1 ? -1 : res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int T;
    cin >> T;
    for (int t = 0; t < T; t++) {
        string A, B;
        cin >> A >> B;
        cout << min_cost_to_transform(A, B) << "\n";
    }

    return 0;
}
