class Solution {
public:
    int numberOfGoodPartitions(vector<int>& nums) {
        const int MOD = 1e9 + 7;
        int n = nums.size();
        unordered_map<int, int> last;
        for (int i = 0; i < n; ++i) {
            last[nums[i]] = i;
        }

        vector<int> dp(n + 1, 0);
        dp[0] = 1;
        for (int i = 1; i <= n; ++i) {
            if (last[nums[i - 1]] == i - 1) {
                dp[i] = dp[i - 1];
            }
            int j = last[nums[i - 1]];
            if (j > 0) {
                dp[i] = (dp[i] + dp[j]) % MOD;
            }
        }
        return dp[n];
    }
};

