#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;
const int mod = 1e9 + 7;
vector<long long> fact, inv_fact;
void precompute_factorials(int n) {
    fact.resize(n + 1);
    inv_fact.resize(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; i++) {
        fact[i] = (fact[i - 1] * i) % mod;
    }
    inv_fact[n] = pow(fact[n], mod - 2, mod);
    for (int i = n - 1; i >= 0; i--) {
        inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % mod;
    }
}
long long permute(int n, int k) {
    if (k > n + n || k < 2) return 0;
    long long total_permutations = fact[n];
    long long invalid_permutations = 0;
    for (int i = 1; i <= n; i++) {
        int complement = k - i;
        if (complement >= 1 && complement <= n && complement != i) {
            invalid_permutations += fact[n - 2];
            invalid_permutations %= mod;
        } else if (complement == i) {
            invalid_permutations += fact[n - 1];
            invalid_permutations %= mod;
        }
    }
    long long valid_permutations = (total_permutations - invalid_permutations + mod) % mod;
    return valid_permutations;
}
