    vector<int> lexicographicallySmallestArray(vector<int>& nums, int limit) {
        int n = nums.size();
        vector<int> pos(n);
        for (int i = 0; i < n; i++) {
            pos[i] = i;
        }
        sort(pos.begin(), pos.end(), [&](int i, int j) {
            return nums[i] < nums[j];
        });
        vector<int> vis(n);
        vector<int> ans(n);
        for (int i = 0; i < n; i++) {
            if (vis[i]) continue;
            int j = i;
            vector<int> group;
            while (!vis[j]) {
                group.push_back(j);
                vis[j] = 1;
                j = pos[j];
            }
            sort(group.begin(), group.end(), [&](int a, int b) {
                return nums[a] < nums[b];
            });
            int base = nums[group[0]];
            for (int k = 0; k < group.size(); k++) {
                ans[group[k]] = base + k;
            }
        }
        return ans;
    }
};

