class Solution {
public:
    long long incremovableSubarrayCount(vector<int>& nums) {
        int n = nums.size();
        int left = 0, right = n - 1;
        while (left + 1 < n && nums[left] < nums[left + 1]) left++;
        while (right > 0 && nums[right] > nums[right - 1]) right--;
        long long res = (long long)(left + 1) * (n - right);
        int l = 0, r = 0;
        for (int i = 0; i < n; i++) {
            while (l < i && nums[i] <= nums[l]) l++;
            while (r < i && nums[i] >= nums[r]) r++;
            res += max(0, min(i - l, r - i) + 1);
        }
        return res;
    }
};

