            while (charCount[s[end] - 'a'] >= 3) {
                maxLen = max(maxLen, end - start + 1);
                leftCounts[s[start] - 'a']++;
                if (leftCounts[s[start] - 'a'] == 3) {
                    maxLen = max(maxLen, end - start + 1);
                }
                charCount[s[start] - 'a']--;
                start++;
            }
        }
        return maxLen;
    }
};

class Solution {
public:
    int maximumLength(string s) {
        int n = s.size();
        int maxLen = -1;
        for (char c = 'a'; c <= 'z'; c++) {
            int count = 0;
            int currLen = 0;
            for (int i = 0; i < n; i++) {
                if (s[i] == c) {
                    currLen++;
                    count++;
                } else {
                    currLen = 0;
                    count = 0;
                }
                if (count >= 3) {
                    maxLen = max(maxLen, currLen);
                }
            }
        }
        return maxLen;
    }
};

