class Solution {
public:
    int maximizeSquareHoleArea(int n, int m, vector<int>& hBars, vector<int>& vBars) {
        sort(hBars.begin(), hBars.end());
        sort(vBars.begin(), vBars.end());

        auto getMaxGap = [](const vector<int>& bars, int maxLen) {
            int maxGap = 0;
            for (int i = 1; i < bars.size(); ++i) {
                maxGap = max(maxGap, bars[i] - bars[i - 1] - 1);
            }
            return min(maxGap, maxLen);
        };

        int maxSide = getMaxGap(hBars, n);
        int maxSide2 = getMaxGap(vBars, m);

        return maxSide * maxSide2;
    }
};

