        int N, P;
        cin >> N >> P;
        vector<int> A(N);
        for (int i = 0; i < N; i++) {
            cin >> A[i];
        }
        vector<int> t(N);
        for (int i = 0; i < N; i++) {
            if (A[i] == 0) {
                t[i] = 0;
            } else {
                t[i] = numeric_limits<int>::max();
            }
        }

        for (int i = 0; i < N; i++) {
            if (A[i] > 0) {
                int left_distance = numeric_limits<int>::max();
                int right_distance = numeric_limits<int>::max();
                for (int j = i - 1; j >= 0; j--) {
                    if (A[j] == 0) {
                        continue;
                    } else if (A[j] > i - j + A[i]) {
                        break;
                    } else {
                        left_distance = min(left_distance, i - j);
                    }
                }
                for (int j = i + 1; j < N; j++) {
                    if (A[j] == 0) {
                        continue;
                    } else if (A[j] > j - i + A[i]) {
                        break;
                    } else {
                        right_distance = min(right_distance, j - i);
                    }
                }
                if (left_distance != numeric_limits<int>::max()) {
                    t[i] = min(t[i], (left_distance * P + A[i] - 1) / P);
                }
                if (right_distance != numeric_limits<int>::max()) {
                    t[i] = min(t[i], (right_distance * P + A[i] - 1) / P);
                }
            }
        }
        for (int i = 0; i < N; i++) {
            if (A[i] > 0) {
                t[i] = (A[i] - 1) / P + 1;
            }
            cout << t[i] << " ";
        }
        cout << endl;
    }
    return 0;
}

