        unordered_map<char, unordered_map<char, long long>> graph;
        for (int i = 0; i < original.size(); ++i) {
            char from = original[i], to = changed[i];
            graph[from][to] = min(graph[from][to], (long long)cost[i]);
        }

        for (char c = 'a'; c <= 'z'; ++c) {
            graph[c][c] = 0;
        }

        for (char mid = 'a'; mid <= 'z'; ++mid) {
            for (char from = 'a'; from <= 'z'; ++from) {
                for (char to = 'a'; to <= 'z'; ++to) {
                    if (graph[from][mid] != INF && graph[mid][to] != INF) {
                        graph[from][to] = min(graph[from][to], graph[from][mid] + graph[mid][to]);
                    }
                }
            }
        }

        long long res = 0;
        for (int i = 0; i < source.size(); ++i) {
            char from = source[i], to = target[i];
            if (graph[from][to] == INF) {
                return -1;
            }
            res += graph[from][to];
        }
        return res;
    }
};

