    long long maximumSubarraySum(vector<int>& nums, int k) {
        int n = nums.size();
        long long max_sum = 0;
        long long prefix_sum = 0;
        unordered_map<int, long long> seen;
        seen[nums[0]] = nums[0];
        prefix_sum = nums[0];

        for (int i = 1; i < n; i++) {
            prefix_sum += nums[i];
            if (seen.find(nums[i] - k) != seen.end()) {
                max_sum = max(max_sum, prefix_sum - (prefix_sum - seen[nums[i] - k]));
            }
            if (seen.find(nums[i] + k) != seen.end()) {
                max_sum = max(max_sum, prefix_sum - (prefix_sum - seen[nums[i] + k]));
            }
            seen[nums[i]] = max(nums[i], seen[nums[i]] + nums[i]);
        }

        return max_sum;
    }
};

