class Solution {
public:
    int minOperations(vector<int>& nums, int k) {
        priority_queue<int, vector<int>, greater<int>> pq;
        for (int num : nums) {
            pq.push(num);
        }
        int count = 0;
        while (!pq.empty() && pq.top() < k) {
            pq.pop();
            count++;
        }
        return count;
    }
};

