class Solution {
public:
    int maximumPoints(vector<int>& enemyEnergies, int currentEnergy) {
        sort(enemyEnergies.begin(), enemyEnergies.end());
        int n = enemyEnergies.size();
        vector<int> dp(currentEnergy + 1, 0);

        for (int i = 0; i < n; i++) {
            int energy = enemyEnergies[i];
            for (int j = currentEnergy; j >= energy; j--) {
                dp[j] = max(dp[j], dp[j - energy] + 1);
