        vector<int> res;
        int n = s.size(), m = a.size(), l = b.size();
        vector<int> aIndices, bIndices;

        // KMP for string a
        vector<int> aLPS(m, 0);
        int length = 0;
        for (int i = 1; i < m; ++i) {
            while (length > 0 && a[i] != a[length]) {
                length = aLPS[length - 1];
            }
            if (a[i] == a[length]) {
                length++;
            }
            aLPS[i] = length;
        }
        int i = 0, j = 0;
        while (i < n) {
            if (a[j] == s[i]) {
                i++;
                j++;
            }
            if (j == m) {
                aIndices.push_back(i - j);
                j = aLPS[j - 1];
            } else if (i < n && a[j] != s[i]) {
                if (j != 0) {
                    j = aLPS[j - 1];
                } else {
                    i++;
                }
            }
        }

        // KMP for string b
        vector<int> bLPS(l, 0);
        length = 0;
        for (int i = 1; i < l; ++i) {
            while (length > 0 && b[i] != b[length]) {
                length = bLPS[length - 1];
            }
            if (b[i] == b[length]) {
                length++;
            }
            bLPS[i] = length;
        }
        i = 0, j = 0;
        while (i < n) {
            if (b[j] == s[i]) {
                i++;
                j++;
            }
            if (j == l) {
                bIndices.push_back(i - j);
                j = bLPS[j - 1];
            } else if (i < n && b[j] != s[i]) {
                if (j != 0) {
                    j = bLPS[j - 1];
                } else {
                    i++;
                }
            }
        }

        // Binary search for bIndices
        for (int i : aIndices) {
            int left = max(0, i - k), right = min((int)s.size() - 1, i + k);
            auto it = lower_bound(bIndices.begin(), bIndices.end(), left);
            if (it != bIndices.end() && *it <= right) {
                res.push_back(i);
            }
        }

