class Solution {
public:
    vector<int> beautifulIndices(string s, string a, string b, int k) {
        vector<int> res;
        int n = s.size(), m = a.size(), l = b.size();
        vector<int> aIndices, bIndices;

        // KMP algorithm for substring search
        vector<int> computeLPS(string pattern) {
            int j = 0;
            vector<int> lps(pattern.size(), 0);
            for (int i = 1; i < pattern.size(); ++i) {
                while (j > 0 && pattern[i] != pattern[j]) j = lps[j - 1];
                if (pattern[i] == pattern[j]) ++j;
                lps[i] = j;
            }
            return lps;
        }

        auto kmpSearch = [&](string text, string pattern) {
            vector<int> lps = computeLPS(pattern);
            vector<int>& indices = pattern == a ? aIndices : bIndices;
            int j = 0;
            for (int i = 0; i < text.size(); ++i) {
                while (j > 0 && text[i] != pattern[j]) j = lps[j - 1];
                if (text[i] == pattern[j]) ++j;
                if (j == pattern.size()) {
                    indices.push_back(i - pattern.size() + 1);
                    j = lps[j - 1];
                }
            }
        };

        kmpSearch(s, a);
        kmpSearch(s, b);

        // Binary search for beautiful indices
        for (int i : aIndices) {
            int left = max(0, i - k), right = min((int)s.size() - 1, i + k);
            auto it = lower_bound(bIndices.begin(), bIndices.end(), left);
            if (it != bIndices.end() && *it <= right) {
                res.push_back(i);
            }
        }

        return res;
    }
};

