        priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
        pq.push({0, 0});

        while (!pq.empty()) {
            long long currCost = pq.top().first;
            int currIdx = pq.top().second;
            pq.pop();

            if (currCost > dist[currIdx]) continue;

            // Explore the neighbors of the current character
            for (auto& nextChar : graph[source[currIdx]]) {
                long long nextCost = currCost + nextChar.second;
                if (nextCost < dist[currIdx + 1]) {
                    dist[currIdx + 1] = nextCost;
                    pq.push({nextCost, currIdx + 1});
                }
            }
        }

