                dp[i][j] = (dp[i - 1][j] + dp[i - 1][j - 1]) % mod;
            }
        }

        int res = 0;
        for (int len = 1; len <= n - k + 1; len++) {
            int left = 0, right = len - 1;
            int rightCnt = n - k;
            while (rightCnt-- >= 0) {
                int power = nums[right + len + k - 1] - nums[left + len - 1];
                res = (res + (long long)power * dp[n - k - len][k - 1]) % mod;
                left++, right++;
            }
        }
        return res;
    }
};

