            long long moves = 0;
            if (l > 0) {
                moves += ones[l - 1] - ones[0];
            }
            if (r < m - 1) {
                moves += ones.back() - ones[r];
            }
            moves += (k - i - l) * 2;
            res = min(res, moves);
            if (moves > maxChanges * 2 + (k - i) * 2) break;
        }
        return min(res, (long long)k + maxChanges);
    }
};

