class Solution {
public:
    int minimumSubarrayLength(vector<int>& nums, int k) {
        int n = nums.size();
        int ans = n + 1;
        int bitmask = 0;
        int dp[64] = {n + 1};
        dp[0] = 0;
        for (int i = 0; i < n; i++) {
            bitmask |= nums[i];
            for (int j = 0; j < 64; j++) {
                if ((bitmask | j) >= k) {
                    ans = min(ans, i + 1 - dp[j]);
                }
            }
            for (int j = 0; j < 64; j++) {
                dp[j | nums[i]] = min(dp[j | nums[i]], dp[j] + 1);
            }
            dp[nums[i]] = min(dp[nums[i]], 1);
        }
        return ans > n ? -1 : ans;
    }
};

