class Solution {
public:
    int countSubmatrices(vector<vector<int>>& grid, int k) {
        int m = grid.size();
        int n = grid[0].size();
        int prefix_sum[m + 1][n + 1];
        memset(prefix_sum, 0, sizeof(prefix_sum));

        for (int i = 1; i <= m; ++i) {
            for (int j = 1; j <= n; ++j) {
                prefix_sum[i][j] = prefix_sum[i - 1][j] + prefix_sum[i][j - 1] - prefix_sum[i - 1][j - 1] + grid[i - 1][j - 1];
            }
        }

        int count = 0;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                for (int x = i; x < m; ++x) {
                    for (int y = j; y < n; ++y) {
                        int sum = prefix_sum[x + 1][y + 1] - prefix_sum[x + 1][j] - prefix_sum[i][y + 1] + prefix_sum[i][j];
                        if (sum <= k && i == 0 && j == 0) {
                            count++;
                        } else if (sum <= k && (i > 0 || j > 0)) {
                            if (i > 0 && j > 0) {
                                int top_left_sum = prefix_sum[i][j];
                                if (sum + top_left_sum - grid[i][j] <= k) count++;
                            } else if (i > 0) {
                                if (sum - grid[i][j] <= k) count++;
                            } else if (j > 0) {
                                if (sum - grid[i][j] <= k) count++;
                            }
                        }
                    }
                }
            }
        }
        return count;
    }
};

