        int n = text.length(), m = pattern.length();
        vector<int> lps(m, 0);
        int j = 0;
        compute_lps_array(pattern, m, lps);
        int i = 0;
        while (i < n) {
            if (pattern[j] == text[i]) {
                i++;
                j++;
            }
            if (j == m) {
                return true;
            }
            else if (i < n && pattern[j] != text[i]) {
                if (j != 0) {
                    j = lps[j - 1];
                }
                else {
                    i++;
                }
            }
        }
        return false;
    }

    void compute_lps_array(string pattern, int m, vector<int>& lps) {
        int length = 0;
        lps[0] = 0;
        int i = 1;
        while (i < m) {
            if (pattern[i] == pattern[length]) {
                length++;
                lps[i] = length;
                i++;
            }
            else {
                if (length != 0) {
                    length = lps[length - 1];
                }
                else {
                    lps[i] = 0;
                    i++;
                }
            }
        }
    }
};

class Solution {
public:
    bool isSubstringPresent(string s) {
        const int n = s.size();
        const int mod = 1e9 + 7;
        const int p = 31;
        long long hs = 0, hr = 0;
        long long powP[101] = {1};
        for (int i = 1; i <= 100; i++) {
            powP[i] = (powP[i-1] * p) % mod;
        }
        for (int i = 0; i < n; i++) {
            hs = (hs * p + s[i]) % mod;
            hr = (hr + s[n-1-i] * powP[i]) % mod;
            if (i >= 1 && hs == hr) {
                return true;
            }
        }
        return false;
    }
};

