class Solution {
public:
    int waysToReachStair(int k) {
        const int MOD = 1e9 + 7;
        vector<int> fact(2 * k + 2, 1);
        vector<int> ifact(2 * k + 2, 1);
        for (int i = 1; i <= 2 * k + 1; i++) {
            fact[i] = (long long)fact[i - 1] * i % MOD;
        }
        ifact.back() = pow(fact.back(), MOD - 2, MOD);
        for (int i = 2 * k; i >= 0; i--) {
            ifact[i] = (long long)ifact[i + 1] * (i + 1) % MOD;
        }
        auto C = [&](int n, int r) {
            if (n < r) return 0;
            return (long long)fact[n] * ifact[r] % MOD * ifact[n - r] % MOD;
        };
        return C(k + 1, k);
    }
};

