            ifact[i] = (long long)ifact[i + 1] * (i + 1) % MOD;
        }
        auto C = [&](int n, int r) {
            if (n < r) return 0;
            return (long long)fact[n] * ifact[r] % MOD * ifact[n - r] % MOD;
        };
        return C(k + 1, k);
    }
};

class Solution {
public:
    int waysToReachStair(int k) {
        if (k == 0) return 2;
        if (k == 1) return 4;
        long long a = 2, b = 4;
        for (int i = 2; i <= k; i++) {
            long long temp = b;
            b = 2 * b + a;
            a = temp;
            if (b > INT_MAX) break;
        }
        return b;
    }
};

