class Solution {
public:
    int numberOfStableArrays(int zero, int one, int limit) {
        const int MOD = 1e9 + 7;
        dp.resize(zero + 1, vector<int>(one + 1, 0));
        return dfs(zero, one, limit);
    }
private:
    vector<vector<int>> dp;
    int dfs(int z, int o, int lim) {
        if (z == 0 && o == 0) return 1;
        if (dp[z][o] != 0) return dp[z][o];
        int res = 0;
        if (z > 0 && lim > 1) {
            res = (res + dfs(z - 1, o, lim - 1)) % MOD;
        }
        if (o > 0 && lim > 1) {
            res = (res + dfs(z, o - 1, lim - 1)) % MOD;
        }
        dp[z][o] = res;
        return res;
    }
};

