class Solution {
public:
    int numberOfStableArrays(int zero, int one, int limit) {
        const int MOD = 1e9 + 7;
        vector<vector<int>> dp(zero + 1, vector<int>(one + 1, 0));
        dp[0][0] = 1;
        for (int z = 0; z <= zero; ++z) {
            for (int o = 0; o <= one; ++o) {
                if (z > 0 && limit > 1) {
                    dp[z][o] = (dp[z][o] + dp[z - 1][o]) % MOD;
                }
                if (o > 0 && limit > 1) {
                    dp[z][o] = (dp[z][o] + dp[z][o - 1]) % MOD;
                }
            }
        }
        return dp[zero][one];
    }
};

