    vector<int> minimumCost(int n, vector<vector<int>>& edges, vector<vector<int>>& query) {
        vector<int> g[n];
        for(auto e : edges) {
            int u = e[0], v = e[1], w = e[2];
            g[u].push_back({v, w});
            g[v].push_back({u, w});
        }

        vector<int> res(query.size(), -1);
        for(int i = 0; i < query.size(); i++) {
            int s = query[i][0], t = query[i][1];
            if(s == t) {
                res[i] = -1;
                continue;
            }
            queue<pair<int, int>> q;
            unordered_set<int> st;
            q.push({s, -1});
            st.insert(s);
            while(!q.empty()) {
                auto [node, cost] = q.front(); q.pop();
                if(node == t) {
                    res[i] = cost == -1 ? -1 : cost;
                    break;
                }
                for(auto [ne, w] : g[node]) {
                    if(st.find(ne) == st.end()) {
                        st.insert(ne);
                        q.push({ne, cost == -1 ? w : cost & w});
                    }
                }
            }
        }
        return res;
    }
};

