class Solution {
public:
    string findLatestTime(string s) {
        int hours = 0, minutes = 0;
        hours = (s[0] - '0') * 10 + (s[1] - '0');
        minutes = (s[3] - '0') * 10 + (s[4] - '0');

        if (s[0] == '?') {
            hours = 11;
        } else if (s[0] == '0') {
            hours = 0;
        } else if (s[0] == '1') {
            if (s[1] == '?') hours = 11;
            else if (s[1] - '0' <= 1) hours = 10 + (s[1] - '0');
        }

        if (s[1] == '?') {
            if (hours == 0) hours = 9;
            else if (hours == 1) hours = 11;
        }

        if (s[3] == '?') minutes = 59;
        if (s[4] == '?') minutes = (minutes / 10) * 10 + 9;

        return to_string(hours / 10) + (hours % 10 < 10 ? "" : to_string(hours % 10)) + ":" +
               to_string(minutes / 10) + to_string(minutes % 10);
    }
};

