class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> prefix(32, 0);
        int mask = 0;
        for (int i = 0; i < n; ++i) {
            mask &= nums[i];
            if (mask == k) ++prefix[0];
            for (int j = 0; j < 32; ++j) {
                if ((mask & (1 << j)) && (k & (1 << j))) {
                    prefix[j + 1]++;
                }
            }
        }
        long long res = 0;
        for (int cnt : prefix) {
            res += cnt * (cnt + 1) / 2;
        }
        return res;
    }
};

