                if (num % i == 0 || num % (i + 2) == 0) return false;
            }
            return true;
        };

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                for (auto& dir : directions) {
                    int x = i, y = j, num = mat[i][j];
                    while (0 <= x && x < m && 0 <= y && y < n) {
                        num = num * 10 + mat[x][y];
                        if (num > 10 && isPrime(num)) {
                            count[num]++;
                        }
                        x += dir.first;
                        y += dir.second;
                    }
                }
            }
