                    if (i < limit && j < limit) {
                        dp[i][j] = (dp[i - 1][j] + dp[i][j - 1]) % MOD;
                    } else {
                        dp[i][j] = dp[i - 1][j];
                    }
                }
            }
        }
        return dp[zero][one];
    }
};

class Solution {
public:
    int numberOfStableArrays(int zero, int one, int limit) {
        const int MOD = 1e9 + 7;
        int dp[zero + 1][one + 1];
        memset(dp, 0, sizeof(dp));
        dp[0][0] = 1;
        for (int i = 1; i <= zero; ++i) {
            for (int j = 1; j <= one; ++j) {
                if (i >= limit) {
                    dp[i][j] = (dp[i][j] + dp[i - 1][j]) % MOD;
                }
                if (j >= limit) {
                    dp[i][j] = (dp[i][j] + dp[i][j - 1]) % MOD;
                }
                if (i >= limit && j >= limit) {
                    dp[i][j] = (dp[i][j] - dp[i - limit][j - limit]) % MOD;
                }
            }
        }
        return dp[zero][one];
    }
};

