class Solution {
public:
    int numberOfSubstrings(string s, int k) {
        int n = s.size();
        int res = 0;
        for (int i = 0; i < n; ++i) {
            unordered_map<char, int> count;
            for (int j = i; j < n; ++j) {
                ++count[s[j]];
                bool found = false;
                for (auto& pair : count) {
                    if (pair.second >= k) {
                        found = true;
                        break;
                    }
                }
                if (found) {
                    res += n - j;
                }
            }
        }
        return res;
    }
}

