    int numberOfPermutations(int n, vector<vector<int>>& requirements) {
        const int mod = 1e9 + 7;
        vector<vector<int>> dp(n + 1, vector<int>(405, 0));
        dp[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= 400; j++) {
                dp[i][j] = dp[i - 1][j];
                if (j > 0) {
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - (i - 1)]) % mod;
                }
            }
        }

        int res = 0;
        for (auto& req : requirements) {
            int end = req[0], cnt = req[1];
            res = (long long)res + dp[end][cnt] * dp[n - end - 1][0] % mod;
        }

        return res % mod;
    }
};

