class Solution {
public:
    int numberOfPermutations(int n, vector<vector<int>>& requirements) {
        const int mod = 1e9 + 7;
        vector<vector<int>> dp(n + 1, vector<int>(405, 0));
        dp[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= 400; j++) {
                dp[i][j] = dp[i - 1][j];
                if (j >= i - 1) {
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - (i - 1)]) % mod;
                }
            }
        }

        int res = 0;
        for (auto& req : requirements) {
            int end = req[0], cnt = req[1];
            if (dp[end][cnt] == 0) {
                return 0;
            }
            res = (long long)res + dp[end][cnt] * comb(n - end - 1, 0, mod) % mod;
        }

        return res % mod;
    }

    int comb(int n, int k, int mod) {
        if (k > n - k) k = n - k;
        int res = 1;
        for (int i = 0; i < k; i++) {
            res = (long long)res * (n - i) % mod;
            res = (long long)res * pow(i + 1, mod - 2, mod) % mod;
        }
        return res;
    }

    int pow(int a, int b, int mod) {
        int res = 1;
        while (b > 0) {
            if (b & 1) res = (long long)res * a % mod;
            a = (long long)a * a % mod;
            b >>= 1;
        }
        return res;
    }
};

