class Solution {
public:
    vector<int> stringIndices(vector<string>& wordsContainer, vector<string>& wordsQuery) {
        int n = wordsContainer.size();
        vector<int> ans(wordsQuery.size());
        unordered_map<string, int> suffixIndex;

        // Construct a suffix tree for wordsContainer
        for (int i = 0; i < n; i++) {
            string word = wordsContainer[i];
            for (int j = word.size() - 1; j >= 0; j--) {
                string suffix = word.substr(j);
                if (suffixIndex.find(suffix) == suffixIndex.end() || word.size() < wordsContainer[suffixIndex[suffix]].size() || (word.size() == wordsContainer[suffixIndex[suffix]].size() && i < suffixIndex[suffix])) {
                    suffixIndex[suffix] = i;
                }
            }
        }

        // Traverse the suffix tree for each wordsQuery
        for (int i = 0; i < wordsQuery.size(); i++) {
            string word = wordsQuery[i];
            string longestSuffix;
            for (int j = word.size() - 1; j >= 0; j--) {
                string suffix = word.substr(j);
                if (suffixIndex.find(suffix) != suffixIndex.end()) {
                    longestSuffix = suffix;
                    break;
                }
            }
            ans[i] = suffixIndex[longestSuffix];
        }
        return ans;
    }
};

