        int x = 0, y = 0;
        for (const auto& command : commands) {
            switch(command[0]) {
                case 'U': x -= n; break;
                case 'D': x += n; break;
                case 'L': --y; break;
                case 'R': ++y; break;
            }
        }
        return x + y;
    }
}

