class Solution {
public:
    int numberOfSubmatrices(vector<vector<char>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> prefixCountX(m, vector<int>(n, 0));
        vector<vector<int>> prefixCountY(m, vector<int>(n, 0));
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] == 'X') {
                    prefixCountX[i][j] = 1;
                    if (i > 0) prefixCountX[i][j] += prefixCountX[i-1][j];
                    if (j > 0) prefixCountX[i][j] += prefixCountX[i][j-1];
                    if (i > 0 && j > 0) prefixCountX[i][j] -= prefixCountX[i-1][j-1];
                }
                if (grid[i][j] == 'Y') {
                    prefixCountY[i][j] = 1;
                    if (i > 0) prefixCountY[i][j] += prefixCountY[i-1][j];
                    if (j > 0) prefixCountY[i][j] += prefixCountY[i][j-1];
                    if (i > 0 && j > 0) prefixCountY[i][j] -= prefixCountY[i-1][j-1];
                }
            }
        }
        int res = 0;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                int xCount, yCount;
                for (int k = i; k < m; ++k) {
                    for (int col = j; col < n; ++col) {
                        xCount = prefixCountX[k][col];
                        if (i > 0) xCount -= prefixCountX[i-1][col];
                        if (j > 0) xCount -= prefixCountX[k][j-1];
                        if (i > 0 && j > 0) xCount += prefixCountX[i-1][j-1];
                        yCount = prefixCountY[k][col];
                        if (i > 0) yCount -= prefixCountY[i-1][col];
                        if (j > 0) yCount -= prefixCountY[k][j-1];
                        if (i > 0 && j > 0) yCount += prefixCountY[i-1][j-1];
                        if (xCount == yCount && xCount > 0 && grid[0][0] == 'X') {
                            ++res;
                        }
                    }
                }
            }
        }
        return res;
    }
};

