class Solution {
public:
    vector<int> timeTaken(vector<vector<int>>& edges) {
        int n = edges.size() + 1;
        vector<int> times(n);
        vector<vector<int>> adj(n);
        for (auto& edge : edges) {
            adj[edge[0]].push_back(edge[1]);
            adj[edge[1]].push_back(edge[0]);
        }

        for (int i = 0; i < n; ++i) {
            times[i] = bfs(i, adj, n);
        }
        return times;
    }

    int bfs(int start, vector<vector<int>>& adj, int n) {
        queue<pair<int, int>> q; // node, time
        q.push({start, 0});
        vector<bool> visited(n, false);
        visited[start] = true;

        int maxTime = 0;
        while (!q.empty()) {
            auto [node, time] = q.front(); q.pop();
            maxTime = max(maxTime, time);

            for (int neighbor : adj[node]) {
                if (!visited[neighbor]) {
                    visited[neighbor] = true;
                    q.push({neighbor, time + (node % 2 == 0 ? 2 : 1)});
                }
            }
        }
        return maxTime;
    }
};

