class Solution {
public:
    int minStartingIndex(string s, string pattern) {
        int m = pattern.size();
        int mismatch = 0;
        int start = 0;
        for (int i = 0; i < s.size(); i++) {
            if (i >= m && s[start] == pattern[i - m]) {
                mismatch--;
                start++;
            }
            if (s[i] != pattern[i % m]) {
                mismatch++;
                if (mismatch > 1) {
                    mismatch--;
                    start++;
                }
            }
            if (i >= m - 1 && mismatch <= 1) {
                return start;
            }
        }
        return -1;
    }
};

class Solution {
public:
    int minStartingIndex(string s, string pattern) {
        int m = pattern.size();
        vector<int> pattern_freq(26);
        for (char c : pattern) {
            pattern_freq[c - 'a']++;
        }
        int mismatch = 0;
        for (int i = 0; i < s.size(); i++) {
            if (i >= m) {
                pattern_freq[s[i - m] - 'a']++;
            }
            pattern_freq[s[i] - 'a']--;
            if (pattern_freq[s[i] - 'a'] < 0) {
                mismatch++;
            }
            if (i >= m - 1 && mismatch <= 1) {
                return i - m + 1;
            }
        }
        return -1;
    }
}

