class Solution {
    public:
    vector<int> gcdValues(vector<int>& nums, vector<int>& queries) {
        vector<int> gcd_pairs;
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                gcd_pairs.push_back(__gcd(nums[i], nums[j]));
            }
        }
        sort(gcd_pairs.begin(), gcd_pairs.end());
        vector<int> answer;
        for (int query : queries) {
            answer.push_back(gcd_pairs[query]);
        }
        return answer;
    }
};

