            res = (res + a) % mod;
        }
        return res;
    }

    class SegmentTree {
    public:
        vector<int> tree;
        int n;

        SegmentTree(vector<int>& nums) {
            n = nums.size();
            tree.resize(4 * n);
            buildTree(nums, 0, 0, n - 1);
        }

        void buildTree(vector<int>& nums, int node, int start, int end) {
            if (start == end) {
                tree[node] = max(0, nums[start]);
            } else {
                int mid = start + (end - start) / 2;
                buildTree(nums, 2 * node + 1, start, mid);
                buildTree(nums, 2 * node + 2, mid + 1, end);
                tree[node] = max(tree[2 * node + 1], tree[2 * node + 2]);
            }
        }

        void update(int pos, int val) {
            updateTree(0, 0, n - 1, pos, val);
        }

        int query(int left, int right) {
            return queryTree(0, 0, n - 1, left, right);
        }

    private:
        int queryTree(int node, int start, int end, int left, int right) {
            if (left > end || right < start) return 0;
            if (left <= start && end <= right) return tree[node];
            int mid = start + (end - start) / 2;
            int p1 = queryTree(2 * node + 1, start, mid, left, right);
            int p2 = queryTree(2 * node + 2, mid + 1, end, left, right);
            return max(p1, p2);
        }

        void updateTree(int node, int start, int end, int pos, int val) {
            if (start == end) {
                tree[node] = max(0, val);
            } else {
                int mid = start + (end - start) / 2;
                if (pos <= mid) {
                    updateTree(2 * node + 1, start, mid, pos, val);
                } else {
                    updateTree(2 * node + 2, mid + 1, end, pos, val);
                }
                tree[node] = max(tree[2 * node + 1], tree[2 * node + 2]);
            }
        }
    };
};

