        dp[0] = 1;
        int res = 1;
        for (int i = 1; i < n; ++i) {
            vector<int> new_dp(1001);
            prefix_sum.assign(1001, 0);
            for (int x = 0; x <= 1000; ++x) {
                prefix_sum[x] = (prefix_sum[x - 1] + dp[x]) % MOD;
            }
            for (int y = 0; y <= nums[i]; ++y) {
                new_dp[y] = (prefix_sum[nums[i - 1]] - prefix_sum[y - 1] + MOD) % MOD;
            }
            dp = new_dp;
            res = accumulate(dp.begin(), dp.end(), 0LL) % MOD;
        }
        return res;
    }
};

