class Solution {
public:
    int maxFrequency(vector<int>& nums, int k, int numOperations) {
        sort(nums.begin(), nums.end());
        int left = 0, n = nums.size();
        long long sum = 0;
        for (int right = 0; right < n; ++right) {
            sum += nums[right];
            while (nums[right] * (right - left + 1) - sum > k * (right - left)) {
                sum -= nums[left++];
            }
            numOperations -= right - left + 1 - 1;
            if (numOperations < 0) break;
        }
        return min(n, (int) (numOperations + (n - left)));
    }
};

