        vector<int> dp(n, 1);

        for (int i = 1; i < n; i++) {
            if (nums[i] > nums[i - 1]) {
                dp[i] = dp[i - 1] + 1;
            }
        }

        int res = 1;
        for (int i = 0; i < n - 1; i++) {
            res = max(res, min(dp[i], dp[i + 1]));
        }

        return res;
    }
};

