        vector<vector<int>> dp(n + 1, vector<int>(x + 1, 0));
        dp[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= x; j++) {
                dp[i][j] = (long long)dp[i - 1][j] * j % MOD;
            }
            for (int j = 1; j <= x; j++) {
                for (int k = 1; k <= x; k++) {
                    if (j != k) {
                        dp[i][j] = (dp[i][j] + dp[i - 1][k]) % MOD;
                    }
                }
            }
        }
        long long res = 0;
        for (int i = 1; i <= x; i++) {
            res = (res + dp[n][i]) % MOD;
        }
        return (int)(res * pow(y, x, MOD)) % MOD;
    }
};

