class Solution {
public:
    int minValidStrings(vector<string>& words, string target) {
        struct TrieNode {
            unordered_map<char, TrieNode*> children;
            bool isEnd;
            TrieNode() : isEnd(false) {}
        };

        TrieNode* root = new TrieNode();
        for (const auto& word : words) {
            TrieNode* node = root;
            for (char c : word) {
                if (!node->children.count(c)) {
                    node->children[c] = new TrieNode();
                }
                node = node->children[c];
            }
            node->isEnd = true;
        }

        int n = target.size();
        vector<int> dp(n + 1, INT_MAX);
        dp[0] = 0;

        for (int i = 1; i <= n; ++i) {
            for (int j = i - 1; j >= 0; --j) {
                TrieNode* node = root;
                bool found = true;
                for (int k = j; k < i; ++k) {
                    if (!node->children.count(target[k])) {
                        found = false;
                        break;
                    }
                    node = node->children[target[k]];
                }
                if (found && node->isEnd) {
                    dp[i] = min(dp[i], dp[j] + 1);
                }
            }
        }

        return dp[n] == INT_MAX ? -1 : dp[n];
    }
};

class Solution {
public:
