    long long countSubstrings(string s) {
        long long res = 0;
        int n = s.size();
        for (int i = 0; i < n; i++) {
            if (s[i] != '0') {
                res++;
            }
        }
        for (int i = 0; i < n; i++) {
            int mod = 0;
            for (int j = i; j < n; j++) {
                mod = (mod * 10 + s[j] - '0') % (s[j] - '0' ?: 10);
                if (mod == 0) {
                    res++;
                }
            }
        }
        return res;
    }
};

class Solution {
public:
    long long countSubstrings(string s) {
        long long res = 0;
        int n = s.size();
        for (int i = 0; i < n; i++) {
            if (s[i] != '0') {
                res++;
            }
        }
        for (int j = 1; j < 10; j++) {
            long long cnt = 0;
            long long cur = 0;
            for (int i = n - 1; i >= 0; i--) {
                if (s[i] - '0' == j) {
                    cur = cnt + 1;
                }
                if (s[i] != '0') {
                    cnt += cur;
                    res += cnt;
                }
            }
        }
        return res;
    }
};

