            result = (result + count) % MOD;
        }
        return result;
    }

    int powMod(int base, int exponent, int nums, int mod) {
        int res = 1;
        while (exponent > 0) {
            if (exponent % 2 == 1) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            exponent /= 2;
        }
        return (res * nums) % mod;
    }
};

