class Solution {
public:
    int countKReducibleNumbers(string s, int k) {
        int n = s.size();
        long long N = 0;
        for (char c : s) N = (N << 1) + (c - '0');
        const int mod = 1e9 + 7;
        vector<vector<int>> dp(n + 1, vector<int>(k + 1, 0));
        for (int j = 0; j <= k; j++) dp[n][j] = 1;
        for (int i = n - 1; i >= 0; i--) {
            for (int j = 0; j <= k; j++) {
                int cur = (N >> (n - 1 - i)) & 1;
                if (cur == 1) {
                    dp[i][j] = dp[i + 1][j];
                    if (j > 0) dp[i][j] = (dp[i][j] + dp[i + 1][j - 1]) % mod;
                } else {
                    dp[i][j] = dp[i + 1][j];
                }
            }
        }
        return (dp[0][k] - 1 + mod) % mod;
    }
};

