class Solution {
public:
    long long maximizeSumOfWeights(vector<vector<int>>& edges, int k) {
        int n = edges.size() + 1;
        vector<int> degrees(n, 0);
        vector<vector<int>> graph(n);

        for (auto& edge : edges) {
            int u = edge[0], v = edge[1], w = edge[2];
            graph[u].push_back({v, w});
            graph[v].push_back({u, w});
            degrees[u]++;
            degrees[v]++;
        }

        priority_queue<vector<int>> pq;
        for (int i = 0; i < n; i++) {
            for (auto& neighbor : graph[i]) {
                pq.push({neighbor[1], i, neighbor[0]});
            }
        }

        sort(pq, [](vector<int>& a, vector<int>& b) {
            return a[0] > b[0];
        });

        long long maxSum = 0;
        vector<int> usedEdges(n, 0);
        while (!pq.empty()) {
            auto [w, u, v] = pq.top();
            pq.pop();
            if (usedEdges[u] == 0 && usedEdges[v] == 0 && degrees[u] < k && degrees[v] < k) {
                maxSum += w;
                degrees[u]++;
                degrees[v]++;
                usedEdges[u] = 1;
                usedEdges[v] = 1;
            }
        }

        return maxSum;
    }
};

