                for (const auto& node : graph) {
                    for (const auto& edge : node.second) {
                        if (distance.find(node.first) != distance.end() && distance[node.first] * edge.second > distance[edge.first]) {
                            distance[edge.first] = distance[node.first] * edge.second;
                        }
                    }
                }
            }
            return distance;
        };
        unordered_map<string, double> maxRates1 = bellmanFord(graph1, initialCurrency);
        unordered_map<string, double> maxRates2;
        for (const auto& pair : maxRates1) {
            maxRates2[pair.first] = pair.second;
        }
        unordered_map<string, double> temp = bellmanFord(graph2, initialCurrency);
        for (const auto& pair : temp) {
            maxRates2[pair.first] = max(maxRates2[pair.first], pair.second);
        }
        for (const auto& pair : graph1) {
            for (const auto& edge : pair.second) {
                if (maxRates1.find(pair.first) != maxRates1.end()) {
                    maxRates2[edge.first] = max(maxRates2[edge.first], maxRates1[pair.first] * edge.second);
                }
            }
        }
        return maxRates2[initialCurrency];
    }
};

class Solution {
public:
    double maxAmount(string initialCurrency, vector<vector<string>>& pairs1, vector<double>& rates1, vector<vector<string>>& pairs2, vector<double>& rates2) {
        // Create a graph for day 1
        unordered_map<string, vector<pair<string, double>>> graph1;
        for (int i = 0; i < pairs1.size(); i++) {
            graph1[pairs1[i][0]].push_back({pairs1[i][1], rates1[i]});
        }

        // Create a graph for day 2
        unordered_map<string, vector<pair<string, double>>> graph2;
        for (int i = 0; i < pairs2.size(); i++) {
            graph2[pairs2[i][0]].push_back({pairs2[i][1], rates2[i]});
        }

        // Compute maximum rates for day 1
        unordered_map<string, double> maxRates1;
        maxRates1[initialCurrency] = 1.0;
        dfs(graph1, maxRates1, initialCurrency);

        // Compute maximum rates for day 2
        unordered_map<string, double> maxRates2 = maxRates1;
        dfs(graph2, maxRates2, initialCurrency);

        return maxRates2[initialCurrency];
    }

    void dfs(unordered_map<string, vector<pair<string, double>>>& graph, unordered_map<string, double>& maxRates, string currency) {
        if (graph.find(currency) != graph.end()) {
            for (const auto& neighbor : graph[currency]) {
                maxRates[neighbor.first] = max(maxRates[neighbor.first], maxRates[currency] * neighbor.second);
                dfs(graph, maxRates, neighbor.first);
            }
        }
    }
};

