        for (int i = 0; i < n; i++) {
            int start = find(allCurrencies.begin(), allCurrencies.end(), pairs1[i][0]) - allCurrencies.begin();
            int target = find(allCurrencies.begin(), allCurrencies.end(), pairs1[i][1]) - allCurrencies.begin();
