class Solution {
public:
    int distanceSum(int m, int n, int k) {
        const int mod = 1e9 + 7;
        long long total = 0;
        for (int i = 1; i <= k; ++i) {
            total = (total + (long long)i * (k - i)) % mod;
        }

        long long x_sum = 0;
        long long y_sum = 0;
        for (int i = 1; i <= m; ++i) {
            x_sum = (x_sum + (long long)(i - 1) * i) % mod;
        }
        for (int i = 1; i <= n; ++i) {
            y_sum = (y_sum + (long long)(i - 1) * i) % mod;
        }

        long long arrangements = 1;
        long long denominator = 1;
        for (int i = 1; i <= k; ++i) {
            arrangements = (arrangements * (long long)i) % mod;
        }
        for (int i = 1; i <= k; ++i) {
            denominator = (denominator * (long long)i) % mod;
        }
        long long inverse = powMod(denominator, mod - 2, mod);
        arrangements = (arrangements * inverse) % mod;

        long long x_distance = (x_sum * (n * n)) % mod;
        long long y_distance = (y_sum * (m * m)) % mod;

