        }
        sort(points.begin(), points.end());
        set<int> x_values;
        set<int> y_values;
        for (const auto& point : points) {
            x_values.insert(point.first);
            y_values.insert(point.second);
        }
        vector<int> x_unique(x_values.begin(), x_values.end());
        vector<int> y_unique(y_values.begin(), y_values.end());
        int x_size = x_unique.size();
        int y_size = y_unique.size();
        map<int, int> x_map;
        map<int, int> y_map;
        for (int i = 0; i < x_size; i++) {
            x_map[x_unique[i]] = i;
        }
        for (int i = 0; i < y_size; i++) {
            y_map[y_unique[i]] = i;
        }
        vector<vector<int>> count(y_size, vector<int>(x_size, 0));
        for (const auto& point : points) {
            count[y_map[point.second]][x_map[point.first]]++;
