        int n = num.size();
        vector<int> cnt(10, 0);
        for (char c : num) cnt[c - '0']++;

        int sum = 0;
        for (int i = 0; i < 10; i++) sum += i * cnt[i];

        if (sum % 2 != 0) return 0;

        int target = sum / 2;
        vector<vector<int>> dp(cnt.size(), vector(target + 1, 0));
        for (int i = 0; i <= cnt[0]; i++) dp[0][i * 0] = 1;

        for (int i = 1; i < 10; i++) {
            for (int j = 0; j <= target; j++) {
                for (int k = 0; k <= cnt[i] && k * i <= j; k++) {
                    dp[i][j] += dp[i - 1][j - k * i] * comb(cnt[i], k);
                    dp[i][j] %= MOD;
                }
            }
        }

        int res = dp[9][target] * fact(n) % MOD;
        for (int i = 0; i < 10; i++) res = res * pow(fact(cnt[i]), MOD - 2) % MOD;

        return res;
    }

private:
    const int MOD = 1e9 + 7;

    long long fact(int n) {
        long long res = 1;
        for (int i = 2; i <= n; i++) {
            res = res * i % MOD;
        }
        return res;
    }

    long long comb(int n, int k) {
        return fact(n) * pow(fact(k), MOD - 2, MOD) % MOD * pow(fact(n - k), MOD - 2, MOD) % MOD;
    }

    long long pow(long long a, long long b, long long mod = MOD) {
        long long res = 1;
        while (b > 0) {
            if (b & 1) res = res * a % mod;
            a = a * a % mod;
            b >>= 1;
        }
        return res;
    }
};

