                } else if (edge[1] == node && distance[edge[0]] == -1) {
                    distance[edge[0]] = distance[node] + 1;
                    q.push(edge[0]);
                    if (distance[edge[0]] > maxDistance) {
                        maxDistance = distance[edge[0]];
                        maxNode = edge[0];
                    }
                }
            }
        }

        distance = vector<int>(n, -1);
        distance[maxNode] = 0;
        q.push(maxNode);
        while (!q.empty()) {
            int node = q.front();
            q.pop();
            for (auto& edge : edges) {
                if (edge[0] == node && distance[edge[1]] == -1) {
                    distance[edge[1]] = distance[node] + 1;
                    q.push(edge[1]);
                } else if (edge[1] == node && distance[edge[0]] == -1) {
                    distance[edge[0]] = distance[node] + 1;
                    q.push(edge[0]);
                }
            }
        }
        return distance;
    }

    int getSize(vector<vector<int>>& edges, int root, int k, int n) {
        vector<int> distance(n, -1);
        distance[root] = 0;
        queue<int> q;
        q.push(root);
        int count = 0;
        while (!q.empty()) {
            int node = q.front();
            q.pop();
            count++;
            for (auto& edge : edges) {
                if (edge[0] == node && distance[edge[1]] == -1 && distance[node] + 1 <= k) {
                    distance[edge[1]] = distance[node] + 1;
                    q.push(edge[1]);
                } else if (edge[1] == node && distance[edge[0]] == -1 && distance[node] + 1 <= k) {
                    distance[edge[0]] = distance[node] + 1;
                    q.push(edge[0]);
                }
            }
        }
        return count;
    }
};

class Solution {
public:
    vector<int> maxTargetNodes(vector<vector<int>>& edges1, vector<vector<int>>& edges2, int k) {
        int n = edges1.size() + 1;
        int m = edges2.size() + 1;

        vector<int> diameter1 = getDiameter(edges1);
        vector<int> diameter2 = getDiameter(edges2);

        vector<int> answer(n);
        for (int i = 0; i < n; i++) {
            int distance = diameter1[i];
            if (distance > k) {
                answer[i] = getSize(edges1, i, k + 1);
            } else {
                answer[i] = getSize(edges1, i, k) + diameter2[0];
            }
        }
        return answer;
    }

    vector<int> getDiameter(vector<vector<int>>& edges) {
        int n = edges.size() + 1;
        vector<int> distance(n, -1);
        int maxDistance = 0;
        int maxNode = 0;

        queue<int> q;
        q.push(0);
        distance[0] = 0;
        while (!q.empty()) {
            int node = q.front();
            q.pop();
            for (auto& edge : edges) {
                int next = edge[0] == node ? edge[1] : edge[0];
                if (distance[next] == -1) {
                    distance[next] = distance[node] + 1;
                    q.push(next);
                    if (distance[next] > maxDistance) {
                        maxDistance = distance[next];
                        maxNode = next;
                    }
                }
            }
        }

        distance = vector<int>(n, -1);
        distance[maxNode] = 0;
        q.push(maxNode);
        while (!q.empty()) {
            int node = q.front();
            q.pop();
            for (auto& edge : edges) {
                int next = edge[0] == node ? edge[1] : edge[0];
                if (distance[next] == -1) {
                    distance[next] = distance[node] + 1;
                    q.push(next);
                }
            }
        }
        return distance;
    }

    int getSize(vector<vector<int>>& edges, int root, int k) {
        int n = edges.size() + 1;
        vector<int> distance(n, -1);
        distance[root] = 0;
        queue<int> q;
        q.push(root);
        int count = 0;
        while (!q.empty()) {
            int node = q.front();
            q.pop();
            count++;
            for (auto& edge : edges) {
                int next = edge[0] == node ? edge[1] : edge[0];
                if (distance[next] == -1 && distance[node] + 1 <= k) {
                    distance[next] = distance[node] + 1;
                    q.push(next);
                }
            }
        }
        return count;
    }
};
